window.NOXIS_I18N = {
  "en": {"meta":{"title":"NOXIS BBQ — ERROR 404: MUSTARD NOT FOUND! 🌭🔥","description":"The mustard is missing, the robot is cooking, and Nyxer is losing his mind! Mustard Hunt, 100 mici order, Nyra the inspector, Z230 the overheated snail and a Comedy Wall."},"nav":{"brand":"NOXIS BBQ","personaje":"NOXIS Crew","mustard":"Mustard Hunt","order":"100 Mici","stress":"Nyxer Stress","nyra":"Feed Nyra","z230":"Z230","comandamente":"Commandments","tipuri":"Griller Types","miciometru":"Mici-O-Meter","quiz":"Quiz","scuze":"Excuses","dictionar":"Dictionary","wall":"Comedy Wall","langLabel":"Language","soundOn":"Sound on","soundOff":"Sound off","menu":"Sections"},"hero":{"badge":"🔥 The only site that smells like BBQ 🔥","titleA":"NOXIS","titleB":"BBQ","tagline":"Where the mustard is missing, the robot is cooking, and Nyxer is losing his mind!","subtitle":"An interactive sci-fi comedy: hunt the missing mustard, order 100 mici (ERROR 402!), feed the cat inspector and keep old Z230 from melting. All that, plus actual grilled mici.","cta1":"Start the Mustard Hunt 🏺","cta2":"Order 100 Mici 🌭","footnote":"* The robot in the photo ate 47 mici during the photo shoot. Nobody stopped him.","caption":"🤖 Chef Robot — the visual star of the NOXIS grill"},"seal":{"alt":"The NOXIS family seal","toast":"The NOXIS Seal hums approvingly. The family is watching the grill."},"generic":{"say":"Say something!","reset":"Reset","close":"Close","attempts":"Attempts"},"characters":{"title":"The NOXIS Crew","subtitle":"One family, one grill, zero mustard. Click a character to hear what they think about it.","familyCta":"See the NOXIS family!","familyTitle":"The NOXIS Family","familySubtitle":"One family. One grill. Infinite chaos.","familyAlt":"The official NOXIS family photo — Tara, Nyxer, Nyxar, Nyxin, AR_ON, AR_IN and Aren","familyCaption":"Official family portrait. The mustard is missing, but the love (and the chaos) is fully present.","roles":{"tara":{"name":"TARA NOXIS","role":"Creator of the NOXIS universe","desc":"Inventive, always bursting with new ideas. She starts projects before Nyxer even finishes the math on the last one."},"nyxer":{"name":"NYXER NOXIS","role":"CFO (Chief Frightened Officer)","desc":"Terrified of expenses, invoices and projects without revenue. Reacts dramatically to any order — even a burger."},"aren":{"name":"AREN NOXIS","role":"Researcher & GitHub explorer","desc":"For every problem he finds another open-source tool. The repo count is rising faster than the grill temperature."},"nyra":{"name":"NYRA","role":"Supreme restaurant inspector","desc":"Independent, ironic, demanding. Considers herself the highest culinary authority in the NOXIS universe. Paws included."},"z230":{"name":"Z230","role":"The family's old computer (as a snail)","desc":"Slow, loyal, warm-hearted. Lives in fear of overheating and of anyone installing new software on him."},"robot":{"name":"CHEF ROBOT","role":"Silver grill master","desc":"Friendly silver robot with glowing blue eyes. Grills mici to perfection and constantly causes absurd situations."},"aron":{"name":"AR_ON NOXIS","role":"Rights & Licenses","desc":"Appears out of nowhere the moment someone uses an image without permission. Says little. His contracts arrive before he does."},"nyxar":{"name":"NYXAR NOXIS","role":"System Administrator","desc":"Keeps the whole NOXIS universe online. Servers, firewall, uptime — his kingdom. Calm like a sysadmin who already made a backup. Of everything. Twice."},"arin":{"name":"AR_IN NOXIS","role":"Keeper of stories","desc":"Tell. Write. Remember. She records every BBQ disaster for future generations — in elegant ice-blue ink."},"nyxin":{"name":"NYXIN NOXIS","role":"Visual Creation","desc":"Draw. Design. Remember. Every pixel of the NOXIS universe is born in her hands — sometimes even during a nap. It simply looks perfect."}},"dialogues":{"tara":["Wait, I have an idea for ANOTHER project!","The mustard disappearance? Inspiring. Very inspiring.","I ordered 100 mici. Financially? Nyxer will explain."],"nyxer":["WHO SPENT MONEY?! WHO?! SHOW ME THE RECEIPT!","13 projects! ZERO revenue! And now no mustard either!","I'm not panicking. I'm... aggressively budgeting."],"aren":["I found an open-source mustard detector on GitHub!","There's a repo for that. There's ALWAYS a repo for that.","I installed 14 new tools. The solution is in one of them. Probably."],"nyra":["Miau. I know where the mustard is. But information costs.","Your grilling technique? Two paws down.","I inspected the kitchen. It passed. Barely. Because of me."],"z230":["If you install anything else on me, I'll turn into a grilled snail!","Loading... slowly... as always... give me... a minute...","My fans are singing. That's not a good sign."],"robot":["I prepared 100 mici. The mustard is not in the inventory!","Grilling level: perfection. Mustard level: ERROR 404.","I don't eat. I only cook. It's a tragedy for everyone else."],"aron":["The fire spoke to me. It said: more charcoal.","I don't hunt the mustard. The mustard hunts me.","Darkness, silence... and the smell of mici. Perfect."],"nyxar":["Have you tried turning the grill off and on again?","I don't have problems. I have tickets. And they're all closed.","The mustard is not in the database. I checked. Twice. With JOINs."],"arin":["Day 1 of the mustard crisis. I am writing everything down.","Every legend needs a chronicler. And every grill needs a witness.","Tell. Write. Remember. Especially the part where the jar went missing."],"nyxin":["I dreamed the site worked. Then I woke up and it did.","I fixed the bug in my sleep. You're welcome.","You are not lost. You are creating. Also, the mustard is in the fridge."]}},"mustard":{"title":"The Great Mustard Hunt","subtitle":"The mici are ready. The mustard has vanished. Search the NOXIS kitchen and find the jar — follow the clues!","errorTitle":"ERROR 404 — MUSTARD NOT FOUND!","robotAnnounce":"Chef Robot announces: the mici are ready... but the mustard is NOT in the inventory!","start":"Start the search!","searchHint":"Click (or press Enter) on an object to search it.","attemptsLabel":"Searches","spots":["Refrigerator","Upper cabinet","Lower cabinet","Oven","Microwave","Spice rack","Cookie jar","Under the sink","Pantry","Trash bin","Toolbox","Christmas decorations box"],"cluesNear":["It's warm here... the mustard is CLOSE!","Nyra smells mustard nearby. She's not talking, though.","The spoon drawer trembles. It must be near!"],"cluesFar":["Nothing here. The mustard is somewhere FAR from this spot.","Z230 scanned the area: mustard probability, 3%. Look elsewhere.","Cold. Colder than Nyxer's reaction to this month's invoices."],"decoys":[{"title":"A ketchup bottle!","text":"It's ketchup. KETCHUP. Nyra is offended you even touched it."},{"title":"One lost sock...","text":"Why is there a sock in the kitchen? The NOXIS family has questions. No answers."},{"title":"Nyra's favorite toy!","text":"A tiny stuffed mouse. You put it back very, very carefully."}],"reactions":{"robot":["Mustard still missing. Recalculating recipes without it. Sadness level: rising.","I checked my inventory twice. The jar refuses to exist."],"nyxer":["WHO BOUGHT 100 MICI WITHOUT MUSTARD?!","Do you know what mustard costs now?! It doesn't matter, WE HAVE NONE!"],"aren":["I found an open-source mustard detector on GitHub! It needs 14 dependencies.","New repo discovered: 'mustard-tracker-9000'. Last commit: 3 years ago. Perfect."],"nyra":["Miau. I know exactly where it is. But information costs.","Amateurs. I found it in 3 seconds. With my eyes closed. On purpose."],"z230":["If you install one more mustard-scanning app on me, I'll turn into a grilled snail!","Scanning... slowly... the... kitchen... please... wait..."],"tara":["Search better! Meanwhile, I have an idea for another project!","The mustard crisis inspired me. I'm designing a mustard-themed theme park."],"aron":["I sense... a jar. Or a shadow. Mostly a shadow.","The darkness hides many things. Mustard included. Unfortunately."],"nyxar":["I deployed a mustard-search service. Uptime: 100%. Jars found: 0.","Server logs say Nyra took it. I'm not judging. I'm just logging."]},"win":{"title":"MUSTARD FOUND! ...or is it?","found":"You found the jar! Hidden by absolutely nobody, visible to everyone.","empty":"You open it slowly... IT'S EMPTY.","robotConfession":"Chef Robot confesses: \"I used the last drop of mustard for the 100 mici. My logic circuits regret nothing.\"","nyraLine":"Nyra: \"Miau. I knew it all along. Information costs, remember?\"","again":"Hunt again (maybe this time there's mustard)"}},"order402":{"title":"Order 100 Mici","subtitle":"One button. One order. One CFO's complete nervous breakdown.","button":"ORDER 100 MICI!","errorTitle":"ERROR 402 — PAYMENT REQUIRED!","errorSub":"The NOXIS financial system has been notified. And by 'notified' we mean 'set on fire'.","panic":["Nyxer: \"ONE HUNDRED mici?! Who approved this?! WHO HAS THE BUDGET?!\"","Nyxer: \"Charcoal, meat, spices, napkins... multiplying... the numbers are MULTIPLYING!\"","Nyxer: \"We are a comedy website, not a catering company!\""],"taraLine":"Tara: \"Nyxer, breathe. It's a simulation. Nobody is buying anything.\"","nyxerFinal":"Nyxer: \"NOT EVEN THE MICI ARE REAL?!\"","disclaimer":"Pure comedy: no real payments, no bank details, no actual mici were ordered. Your wallet is safe. Nyxer's isn't.","again":"Order again (Nyxer loves that)"},"stress":{"title":"Nyxer Stress Level","subtitle":"A live meter of the NOXIS CFO's nerves. Every event on this site feeds it. Enjoy responsibly.","reasons":{"order":"Someone ordered 100 mici for free.","mustard":"The mustard hunt ended. The jar was empty.","wrongSearch":"Another wrong search in the kitchen.","chaosTara":"Tara started a brand new project.","chaosAren":"Aren discovered yet another skill on GitHub.","chaosRobot":"The robot ordered more ingredients.","chaosNyra":"Nyra demanded a special menu.","chaosZ230":"Z230 threatened to shut down.","nyraMenu":"Nyra's special menu was approved.","z230hot":"Z230 is dangerously close to melting."},"levels":{"calm":"Nyxer is calm. Suspiciously calm.","worried":"Nyxer is checking invoices. Again.","panicked":"Nyxer is speed-walking between spreadsheets.","meltdown":"TOTAL MELTDOWN. Cover the calculators!"},"shout":"13 PROJECTS! ZERO REVENUE! AND NOW WE DON'T EVEN HAVE MUSTARD!","chaos":"Cause random chaos","reset":"Give Nyxer a beer 🍺","logTitle":"Latest incidents:","emptyLog":"Nothing happened yet. Nyxer doesn't trust it.","afterReset":"Nyxer: \"I'm calm now. Perfectly calm. Don't touch anything.\""},"nyra":{"title":"Feed Nyra","subtitle":"Offer dishes to the supreme inspector. She accepts some, rejects most, judges always.","foods":{"salmon":"Grilled salmon","chicken":"Plain chicken","egg":"Boiled egg","cheese":"Cheese cube","shrimp":"Shrimp","milk":"Cow's milk","onion":"Onion","garlic":"Garlic","chocolate":"Chocolate","grapes":"Grapes"},"offer":"Offer","accepted":["Miau. Acceptable. For a human.","Nyra tastes it. Slowly. \"I've had better. Add it to my file.\"","\"Edible. The service is still terrible.\""],"disdain":["Nyra looks at the dish. Then at you. Then back at the dish. \"No.\"","\"Miau. I inspect restaurants. I don't eat their mistakes.\"","She sniffs it once and walks away with royal disappointment."],"reject":["\"{food}?! Are you trying to poison the inspector?! That's TOXIC for cats!\"","\"Absolutely not. {food} is dangerous for felines. One star. If I could give zero, I would.\"","\"{food} — rejected. My whiskers detect danger. And bad taste.\""],"specialMenu":"Nyra composed her special menu.","nyxerQuestion":"Nyxer: \"Wait... how much does the special menu COST?\"","nyraAnswer":"Nyra: \"Miau. Put it on YOUR bill!\"","vetNote":"Comedy game — in real life, never feed cats BBQ food. Onions, garlic, chocolate and grapes are toxic for cats. When in doubt: ask the vet.","unsafeLabel":"Dangerous for cats","safeLabel":"Cat-safe (in the game)"},"z230":{"title":"Z230 — The Overheated Snail","subtitle":"The family's old computer watches the grill with horror. Start the BBQ and see how long he survives.","start":"START THE GRILL!","stop":"Cool down (save the snail)","react":"Z230: \"NOT ON MY PROCESSOR!\"","lines":{"warm":["Z230: \"Is it getting warm in here or is it just me?\"","Z230: \"I'm opening all my fans. All of them. I have two.\""],"hot":["Z230: \"I am officially a snail fondue. This is not a metaphor.\"","Z230: \"If I freeze now, tell my files I loved them.\""],"critical":["Z230: \"EMERGENCY! I'm one degree away from becoming a grilled snail!\"","Z230: \"Shutting down in 3... 2... unless someone cools me down NOW!\""]},"tempLabel":"Comic temperature","disclaimer":"Units are 100% comedy (°SN — Snail Units). This thermometer measures absolutely nothing real.","shutdown":"Z230 fainted dramatically. He'll be fine. He always is."},"wall":{"title":"NOXIS BBQ — Comedy Wall","subtitle":"Leave a joke, a comment, a barbecue confession. In any language. Nyra will judge it anyway.","nickname":"Nickname","nicknamePh":"e.g. MustardFan42","comment":"Comment","commentPh":"Your funniest BBQ story...","post":"Post comment","reply":"Reply","replyPh":"Your reply...","cancelReply":"Cancel","like":"Like","deleted":"Comment removed by the moderator. Nyra approved.","adminMode":"Moderator mode","adminPassword":"Moderator password","adminLogin":"Log in","adminLogout":"Log out","delete":"Delete","wrongPassword":"Wrong password. Nyra is watching you.","moderatorOn":"Moderator mode ON.","moderatorOff":"Moderator mode off.","empty":"The wall is empty. Be the first legend!","loading":"Loading the comedy...","postedOk":"Comment posted! The NOXIS family salutes you.","spamFast":"Easy, legend! Too many comments too fast. Try again in a minute.","spamBlocked":"The NOXIS anti-spam snail blocked that. Try something different.","badContent":"Nyra rejected your comment. Keep it friendly and funny!","nicknameBad":"The nickname needs 2-24 characters. Like a proper legend.","commentBad":"The comment needs 2-500 characters.","demoNotice":"No account, no registration: type, post, laugh. Your nickname and comment are visible to all visitors; the IP address is used solely for anti-spam protection and is never displayed.","translate":"Translate","translating":"Translating...","translateNote":"AI translation (real service, may be imperfect).","translateError":"The translation service is unavailable right now. (Nyra probably unplugged it.) The comment stays in its original language — no fake translations here.","translateFast":"The translation machine is cooling down. Give it a few seconds and try again.","offlineTitle":"Public comments need a server","offlineBody":"This NOXIS BBQ version runs directly inside NOXIS UNIVERS, without a server. Public comments, replies, likes, AI translation and moderation only work in the full Next.js version with a backend (see INTEGRARE.md). Nothing is simulated here — Nyra does not tolerate fakes.","offlineHint":"📍 Local note for the UNIVERS — this is NOT a public comments section.","backendDoc":"The BACKEND-NECESAR.md file in the archive describes everything required; the full Next.js version (noxis-bbq-complete.zip) already ships with a ready-made backend.","rules":"Be funny, be kind. No personal data. The snail moderates."},"music":{"welcomeTitle":"WELCOME TO NOXIS BBQ!","welcomeSub":"100 Mici. One Missing Mustard. Infinite Chaos!","enterMusic":"🎸 ENTER NOXIS BBQ — TURN UP THE MUSIC!","enterSilent":"🔇 ENTER WITHOUT MUSIC","play":"Play","pause":"Pause","mute":"Mute","unmute":"Unmute","volume":"Volume","nowPlaying":"Now playing","credits":"TARA NOXIS — WHERE'S THE MUSTARD?! · Music © Tara Noxis"},"comandamente":{"title":"The 10 Commandments of the Grill","subtitle":"Written in smoke on a stainless steel tablet, found next to grandma's grill.","items":[{"title":"Never grill while hungry","text":"You'll eat raw meat out of desperation and convince yourself \"that's how we do it here\". Hold on, hero. At least one slice of bread first."},{"title":"Honor the mustard, for it shall lift you up","text":"Mustard is not a condiment. It's a religion. Eating mici without mustard risks excommunication from the grill guild and judgmental grandma looks."},{"title":"Do not forget the salt!","text":"The god of the grill does not forgive bland meat. Meat without salt is like a joke without a punchline: it exists, but brings no joy."},{"title":"Guard the grill with your life","text":"The neighbor's dogs are watching. The cats are mocking. And Uncle Gheorghe has been \"just looking\" since 2009. Stay close. Always."},{"title":"Smoke in your eyes is the baptism of a true griller","text":"If you haven't cried at the grill at least once, you haven't lived. Smoke tears do NOT count as emotions. They count as certification."},{"title":"Do not count the mici you ate","text":"Count only how happy you are. The mici number is a controversial subject and must never be discussed with your partner or your doctor."},{"title":"Small fire is for rookies, big fire is for heroes","text":"With moderation, though. We don't want to call the firefighters over the third mici. Last year was an accident. This year was \"an experiment\"."},{"title":"Whoever brings the cold beer shall be blessed","text":"Forever and ever, cold beer is the star of the grill sky. Whoever brings warm beer will be gently asked to hold it in their hands until it cools."},{"title":"Do not ask \"is it ready?\"","text":"The grill knows when it's ready. Asking \"is it ready?\" forty times doesn't speed up the process, it just stresses the meat. Meat has feelings too."},{"title":"Love your neighbor, but never give him the first mici","text":"Rules are rules. The first mici belongs to the griller. That's the third law of grill dynamics. We didn't invent it. We just obey."}]},"tipuri":{"title":"The 6 Griller Types","subtitle":"You've met them all. They all exist. One of them might be you. (If you're the Experimenter, please: don't.)","items":[{"name":"The Artist","motto":"\"Every mici is a work of art.\"","desc":"Presents the meat like a biennale exhibition. Photographs each mici 15 times, from 9 angles, before eating it. Then the meat is cold. He doesn't care. Art.","level":"Level: courtyard Louvre"},{"name":"The Philosopher","motto":"\"But what IS a mici, really?\"","desc":"Spends 3 hours at the grill talking about the meaning of life, the universe and everything. Meanwhile the meat burns. \"The smoke is a metaphor\", he says, while the smoke alarm agrees.","level":"Level: Zen in flames"},{"name":"The Ninja","motto":"\"Have you ever seen a ninja wash dishes? Exactly.\"","desc":"Appears exactly when the meat is ready. Disappears exactly when the dishes need washing. Nobody has ever seen him carry charcoal. Urban legends say he exists, but nobody can confirm.","level":"Level: invisible, but fed"},{"name":"The Planner","motto":"\"I made a spreadsheet. You have 5 minutes to read it.\"","desc":"Owns a spreadsheet with mici per person, a 48-hour weather forecast, a cooking-time chart and an evacuation plan. His grill starts on the second. Precise. Terrifying.","level":"Level: backyard NASA"},{"name":"The Experimenter","motto":"\"But what if we add... pineapple?\"","desc":"Puts pineapple on the grill. PINEAPPLE. On. The. Grill. Then tries mici with chocolate \"for science\". The community watches him closely. Chef Robot has filed a formal complaint.","level":"Level: forbidden laboratory"},{"name":"The Veteran","motto":"\"I've been grilling since '87. I accept no criticism.\"","desc":"His meat is always \"perfect\", even when it's carbonized at the molecular level. Has strong opinions about charcoal, wood, fire and life in general. Do not argue. Do not even try.","level":"Level: general, retired"}]},"miciometru":{"title":"Mici-O-Meter 3000","subtitle":"A state-of-the-art medical device that measures how many mici you can eat. Precision: ±0 mici. Just press and see how far you get!","counterLabel":"Mici consumed","unit":"mici devoured with honor","eat":"Eat a mici!","reset":"Reset (the doctor called)","rangs":["Rookie","Grill-Major","Legend"],"legendTarget":"Legend","milestones":["Start, brave one! At least one mici. The robot is watching, waiting. 🤖","Slacker! Even the robot eats more. And he doesn't even have a stomach! 🤖","IT HAS BEGUN! The grandmas are slowly changing their opinion of you.","Respectable! You're already speaking with a Transylvanian accent. Don't know how, but it's nice.","GREAT! Grandma is crying with pride. Or from the smoke. Hard to tell.","You reached the rank of GRILL-MAJOR! Only 30 more ranks to Legend.","Wow. Just wow. Someone is already bringing the second jar of mustard. It's serious.","LEGEND UNDER CONSTRUCTION! The neighbors are starting to gather. Someone brought porcelain from work.","CONFIRMED LEGEND! You must be from Transylvania or from a family of champions.","YOU'VE PASSED HUMAN LIMITS! We're calling the robot to stop you. And he eats a lot, so it's serious. 🤖🚨"],"disclaimer":"* The Mici-O-Meter accepts no responsibility for indigestion, afternoon naps or dreams of running grills."},"quiz":{"title":"Quiz: What Kind of Griller Are You?","subtitle":"Four questions. One destiny. Zero wrong answers (only delicious ones).","qOf":"Question","of":"of","restart":"Retake the quiz, maybe I'll do better 🔁","ghost":"(You answered 0 times? A ghost griller? Impressive.) 👻","resultTitle":"Your result is...","questions":[{"q":"What do you do when someone claims somebody else grills better?","a":["\"Interesting theory. Have you studied the subject? I prepared a 40-page document.\"","\"Everyone has their own path to enlightenment. Let's not judge.\"","\"You smile politely, but in your soul you've already signed up for a duel.\""]},{"q":"When is the perfect moment to light the grill?","a":["\"14:00 sharp. I noted it. Recalculated. I have a backup plan.\"","\"When my heart screams: VERY SLEEPY, BUT ALSO HUNGRY.\"","\"When the light falls at 45 degrees and the sky is Picasso blue.\""]},{"q":"What's the secret of a perfect mici?","a":["\"Patience, love and a bit of smoke in the eyes.\"","\"Not burning it. The rest are just details I've never heard of.\"","\"The secret family recipe. From 1987. I won't say it even under torture.\""]},{"q":"A guest brings pineapple to the grill. Your reaction?","a":["\"Interesting. I'll put it next to the meat, but only for science.\"","\"I photograph the pineapple from 9 angles before anyone breathes.\"","\"I appear from the shadows and confiscate it, discreetly. Nobody ever sees me.\""]}],"results":{"Philosopher":{"name":"Philosopher griller","desc":"You and the grill are one soul. You talk about the meaning of life while the meat cooks itself (usually in the flames). You're wise, calm and the only one who remembers why the fire was started."},"Artist":{"name":"Artist griller","desc":"For you, the grill is a gallery, the plate is a frame and the mustard is a brush. Every mici is photographed, filtered and presented. The meat got cold? No problem. The content is everything."},"Ninja":{"name":"Ninja griller","desc":"Nobody knows where you come from, nobody knows where you go. You appear at the grill exactly when the meat is ready and vanish when the dishes need washing. You are a well-fed urban legend."},"Planner":{"name":"Planner griller","desc":"Your grill is a military operation. You have a spreadsheet with mici per person, weather forecasts and plans B, C and D. Nothing ever goes wrong. Nothing. Ever. (So far.)"},"Experimenter":{"name":"Experimenter griller","desc":"For you, the grill is a laboratory. Mici with chocolate? Yes. Pineapple on the grill? YES. The community watches you, but admits: sometimes, sometimes, you're right. Very rarely. Very."},"Veteran":{"name":"Veteran griller","desc":"You've been grilling for generations. Your meat is always \"perfect\", your fire is always \"correct\" and your opinions about charcoal are laws. Do not argue with the veteran. Do not even try."}}},"scuze":{"title":"The Grill Excuse Generator","subtitle":"Friends invite you to their wedding? To the theater? To \"a healthy walk\"? Don't worry — we have world-class excuses, tested on mothers-in-law.","placeholder":"Press the button and receive a solid excuse, legally verified by Chef Robot. 🤖","generate":"Generate excuse!","counter":"Excuses generated so far","legend":" — you're dropping off the guest lists, but you're the Legend of the grill! 🏆","items":["\"I can't come today. The mici need attention. It's a relationship issue.\"","\"The doctor banned me from grills... other people's grills. Mine is medically prescribed.\"","\"I have an important meeting: the grill and me. 14:00. In the backyard. Cannot be moved.\"","\"Someone has to guard the meat from the curious. I volunteered. I'm basically a hero.\"","\"The car won't start. And it doesn't want to. It smells the grill smoke and refuses to leave.\"","\"I'm allergic to days without BBQ. It's serious. The doctors are confused.\"","\"I can't fly today, but I can grill. Almost the same, just tastier.\"","\"The boss gave me the day off for 'important business'. The mici ARE the business.\"","\"I promised my mother-in-law I'd come... to the grill. I never said where I'd sit. Legal loophole.\"","\"Can't today, but who will test the meat quality? Me. Exactly. We're a team.\"","\"Not today. The meat needs me emotionally. And I need it. It's mutual.\"","\"I sprained my ankle. Trying to put sneakers on the grill. Long story.\"","\"I must stay home. My WiFi awaits. And the upstairs grill. And the fridge.\"","\"I'm in training for the Mici Marathon. Can't interrupt practice. I'm at mici 4 of 40.\"","\"Allergic to smoke, soot and days without BBQ. The doctors are puzzled. I've made peace with it.\""]},"dictionar":{"title":"The Griller's Dictionary","subtitle":"Official terms, legal definitions (not really), approved by the Academy of Backyard Smoking.","items":[{"term":"mici (noun)","phonetic":"/meetch/","def":"The fundamental unit of happiness. 1 mici = 7 standardized units of joy. Served obligatory with mustard and stories. Plural: mici (multiply the happiness)."},{"term":"mustard (noun)","phonetic":"/mus-tard/","def":"The griller's holy liquid. Not a condiment — a sacrament. Poured generously and with faith. Whoever uses ketchup is kindly asked to leave. (Half joking.)"},{"term":"smoke (noun)","phonetic":"/smoke/","def":"The official perfume of summer days and the main cause of neighborly drooling. Detected on clothes months later, as a faithful memory of a perfect day."},{"term":"opportunivore (noun)","phonetic":"/op-por-tu-ni-vore/","def":"A person who arrives at the grill exactly when the food is ready, having brought nothing. Identification: eats at the speed of light, vanishes at dishwashing time."},{"term":"roasted pepper (noun)","phonetic":"/roasted pep-per/","def":"The mici's best friend. Roasts slowly, with dignity, and instantly dumps anyone who eats it without bread. It's a complex but beautiful relationship."},{"term":"\"is it ready?\" (expression)","phonetic":"/is it rea-dy/","def":"Forbidden question no. 1 at the grill. Repeated 40 times, it doesn't speed up the meat, it just stresses the griller. Alternate: \"is it much longer?\" (forbidden no. 2)."},{"term":"grill veteran (noun)","phonetic":"/vet-er-an/","def":"One who has grilled since 1987 and accepts no criticism. His meat is always \"perfect\", even past the carbon state. Respect is enforced through smoke."},{"term":"cold beer (noun)","phonetic":"/beer/","def":"The star of the grill sky. Whoever brings cold beer shall be blessed forever. Whoever brings warm beer shall hold it in their hands, with dignity, until it cools."}]},"footer":{"brand":"🍖 NOXIS BBQ 🍖","copyright":"© 2026 NOXIS Universe — All mici are respected. No meat was intentionally burned while building this site. (Only a little. Twice.)","comedyNote":"Comedy site. The definitions, excuses and ranks are fictional. The mici, however, are very real. Grill responsibly!","musicCredit":"🎵 TARA NOXIS — WHERE'S THE MUSTARD?! · Music © Tara Noxis"}},
  "ro": {"meta":{"title":"NOXIS BBQ — ERROR 404: MUȘTAR NEGAȚIT! 🌭🔥","description":"Muștarul a dispărut, robotul gătește, iar Nyxer își pierde mințile! Vânătoarea muștarului, comandă de 100 de mici, Nyra inspectoarea, Z230 melcul supraîncălzit și Zidul Comediei."},"nav":{"brand":"NOXIS BBQ","personaje":"Echipa NOXIS","mustard":"Vânătoarea Muștarului","order":"100 de Mici","stress":"Stresul lui Nyxer","nyra":"Hrănește-o pe Nyra","z230":"Z230","comandamente":"Comandamente","tipuri":"Tipuri de grătari","miciometru":"Mici-O-Metru","quiz":"Quiz","scuze":"Scuze","dictionar":"Dicționar","wall":"Zidul Comediei","langLabel":"Limba","soundOn":"Sunet activat","soundOff":"Sunet oprit","menu":"Secțiuni"},"hero":{"badge":"🔥 Singurul site care miroase a grătar 🔥","titleA":"NOXIS","titleB":"BBQ","tagline":"Unde muștarul lipsește, robotul gătește, iar Nyxer își pierde mințile!","subtitle":"O comedie SF interactivă: vânează muștarul dispărut, comandă 100 de mici (ERROR 402!), hrănește inspectoarea felină și ține-l pe bătrânul Z230 să nu se topească. Și, da, mai sunt și niște mici grățiți pe aici.","cta1":"Începe Vânătoarea Muștarului 🏺","cta2":"Comandă 100 de Mici 🌭","footnote":"* Robotul din poză a mâncat 47 de mici în timpul ședinței foto. Nimeni nu l-a oprit.","caption":"🤖 Robotul Bucătar — vedeta vizuală a grătarului NOXIS"},"seal":{"alt":"Sigiliul familiei NOXIS","toast":"Sigiliul NOXIS zumzăie aprobator. Familia privește grătarul."},"generic":{"say":"Spune ceva!","reset":"Resetează","close":"Închide","attempts":"Încercări"},"characters":{"title":"Echipa NOXIS","subtitle":"O familie, un grătar, zero muștar. Apasă pe un personaj ca să afli ce crede despre toată situația.","familyCta":"Vezi Familia NOXIS!","familyTitle":"Familia NOXIS","familySubtitle":"O familie. Un grătar. Haos infinit.","familyAlt":"Fotografia oficială a Familiei NOXIS — Tara, Nyxer, Nyxar, Nyxin, AR_ON, AR_IN și Aren","familyCaption":"Portretul oficial de familie. Muștarul lipsește, dar dragostea (și haosul) sunt pe deplin prezente.","roles":{"tara":{"name":"TARA NOXIS","role":"Creatoarea universului NOXIS","desc":"Inventivă, mereu cu idei noi. Pornește proiecte înainte ca Nyxer să termine calculele pentru cel din urmă."},"nyxer":{"name":"NYXER NOXIS","role":"Director financiar (Șef-înfricosat)","desc":"Îngrozit de cheltuieli, facturi și proiecte fără venituri. Reacționează dramatic la orice comandă — chiar și la un burger."},"aren":{"name":"AREN NOXIS","role":"Cercetător & explorator GitHub","desc":"Pentru orice problemă găsește încă un program open-source. Numărul de repo-uri crește mai repede decât temperatura grătarului."},"nyra":{"name":"NYRA","role":"Inspectoarea supremă a restaurantului","desc":"Independentă, ironică, pretențioasă. Se consideră cea mai înaltă autoritate culinară din universul NOXIS. Lăbuțe incluse."},"z230":{"name":"Z230","role":"Calculatorul bătrân al familiei (ca melc)","desc":"Încet, loial, cu inimă caldă. Trăiește cu frica de supraîncălzire și de oricine vrea să-i instaleze programe noi."},"robot":{"name":"ROBOTUL BUCĂTAR","role":"Maestrul argintiu al grătarului","desc":"Robot argintiu simpatic, cu ochi albaștri luminați. Grătește mici perfect și provoacă permanent situații absurde."},"aron":{"name":"AR_ON NOXIS","role":"Drepturi și licențe","desc":"Apare de nicăieri exact când cineva folosește o imagine fără permisiune. Vorbește puțin. Contractele lui ajung înaintea lui."},"nyxar":{"name":"NYXAR NOXIS","role":"Administratorul de sistem","desc":"Ține tot universul NOXIS online. Servere, firewall, uptime — regatul lui. Calm ca un sysadmin care și-a făcut deja backup. La tot. De două ori."},"arin":{"name":"AR_IN NOXIS","role":"Păstrătoarea poveștilor","desc":"Spune. Scrie. Reține. Își notează fiecare dezastru de grătar pentru generațiile viitoare — cu cerneală albastru-gheață."},"nyxin":{"name":"NYXIN NOXIS","role":"Creație vizuală","desc":"Desenează. Proiectează. Reține. Fiecare pixel al universului NOXIS își are originea în mâna ei — uneori chiar în timpul unui pui de somn. Pur și simplu arată perfect."}},"dialogues":{"tara":["Stai, am o idee pentru ÎNCĂ UN proiect!","Dispariția muștarului? Inspirantă. Foarte inspirantă.","Am comandat 100 de mici. Financiar? Explică Nyxer."],"nyxer":["CINE A CHIELTUIT BANI?! CINE?! ARATAȚI-MI BONUL!","13 proiecte! ZERO încasări! ȘI acum nici muștar nu mai e!","Nu fac criză. Fac... bugetare agresivă."],"aren":["Am găsit pe GitHub un detector open-source de muștar!","Există un repo pentru asta. Există ÎNTOTDEAUNA un repo pentru asta.","Am instalat 14 instrumente noi. Soluția e într-unul din ele. Probabil."],"nyra":["Miau. Știu unde e muștarul. Dar informația costă.","Tehnica ta de grătar? Două lăbuțe în jos.","Am inspectat bucătăria. A trecut. Ba chiar din pricina mea."],"z230":["Dacă îmi mai instalați ceva, mă transform în melc la grătar!","Se încarcă... încet... ca de obicei... dați-mi... un minut...","Ventilatoarele mele cântă. Nu e un semn bun."],"robot":["Am pregătit 100 de mici. Muștarul nu figurează în inventar!","Nivel grătar: perfecțiune. Nivel muștar: ERROR 404.","Nu mănânc. Doar gătesc. E o tragedie pentru toți ceilalți."],"aron":["Focul mi-a vorbit. A zis: mai mulți cărbuni.","Eu nu vânez muștarul. Muștarul mă vânează pe mine.","Întuneric, liniște... și miros de mici. Perfect."],"nyxar":["Ați încercat să opriți grătarul și să-l porniți din nou?","Eu nu am probleme. Am tichete. Și toate sunt închise.","Muștarul nu e în baza de date. Am verificat. De două ori. Cu JOIN-uri."],"arin":["Ziua 1 a crizei muștarului. Notez totul.","Orice legendă are nevoie de un cronicar. Iar orice grătar de un martor.","Spune. Scrie. Reține. Mai ales partea în care a dispărut borcanul."],"nyxin":["Am visat că site-ul funcționează. M-am trezit și chiar așa era.","Am reparat bug-ul în somn. Cu plăcere.","Nu ești pierdut, ești în plin proces creativ. Și muștarul e în frigider."]}},"mustard":{"title":"The Great Mustard Hunt — Vânătoarea Muștarului","subtitle":"Micii sunt gata. Muștarul a dispărut. Caută prin bucătăria NOXIS și găsește borcanul — urmărește indiciile!","errorTitle":"ERROR 404 — MUȘTAR NEGAȚIT!","robotAnnounce":"Robotul Bucătar anunță: micii sunt gata... dar muștarul NU figurează în inventar!","start":"Începe căutarea!","searchHint":"Apasă (sau Enter) pe un obiect ca să-l percheziționezi.","attemptsLabel":"Percheziții","spots":["Frigiderul","Dulapul de sus","Dulapul de jos","Cuptorul","Cuptorul cu microunde","Raftul de condimente","Borcanul cu fursecuri","Sub chiuvetă","Cămara","Pubela","Cutia de unelte","Cutia cu decorațiuni de Crăciun"],"cluesNear":["E cald pe aici... muștarul e APROAPE!","Nyra simte miros de muștar în zonă. Dar nu zice nimic.","Sertarul cu linguri tremură. Trebuie să fie aproape!"],"cluesFar":["Nimic aici. Muștarul e undeva DEPARTE de acest loc.","Z230 a scanat zona: probabilitate muștar, 3%. Caută altundeva.","Frig. Mai frig decât reacția lui Nyxer la facturile lunii."],"decoys":[{"title":"O sticlă de ketchup!","text":"E ketchup. KETCHUP. Nyra s-a supărat că ai atins-o măcar."},{"title":"O șosetă pierdută...","text":"De ce e o șosetă în bucătărie? Familia NOXIS are întrebări. Fără răspunsuri."},{"title":"Jucăria preferată a lui Nyra!","text":"Un șoricel de pluș. L-ai pus la loc foarte, foarte atent."}],"reactions":{"robot":["Muștarul încă lipsește. Recalculez rețete fără el. Nivel de tristețe: în creștere.","Mi-am verificat inventarul de două ori. Borcanul refuză să existe."],"nyxer":["CINE A CUMPĂRAT 100 DE MICI FĂRĂ MUȘTAR?!","Știi cât costă muștarul acum?! Nu contează, ORICUM NU AVEM!"],"aren":["Am găsit pe GitHub un detector open-source de muștar! Are 14 dependențe.","Repo nou descoperit: 'mustard-tracker-9000'. Ultimul commit: acum 3 ani. Perfect."],"nyra":["Miau. Știu exact unde e. Dar informația costă.","Amatori. Eu l-am găsit în 3 secunde. Cu ochii închiși. Din principiu."],"z230":["Dacă mai instalați o aplicație de scanat muștar pe mine, mă transform în melc la grătar!","Scanez... încet... bucătăria... aveți... răbdare..."],"tara":["Căutați mai bine! Între timp, am o idee pentru alt proiect!","Criza muștarului m-a inspirat. Proiectez un parc de distracții cu temă de muștar."],"aron":["Simt... un borcan. Sau o umbră. Mai degrabă o umbră.","Întunericul ascunde multe lucruri. Muștar inclusiv. Din păcate."],"nyxar":["Am implementat un serviciu de căutare muștar. Uptime: 100%. Borcane găsite: 0.","Log-urile de server zic că Nyra l-a luat. Nu judec. Doar loghez."]},"win":{"title":"MUȘTAR GĂSIT! ...sau nu?","found":"Ai găsit borcanul! Ascuns de absolut nimeni, vizibil pentru toți.","empty":"Îl deschizi încet... E GOL.","robotConfession":"Robotul Bucătar mărturisește: „Am folosit ultima picătură de muștar pentru cei 100 de mici. Circuitele mele logice nu regretă nimic.”","nyraLine":"Nyra: „Miau. Am știut de la început. Informația costă, amintește-ți.”","again":"Vânează din nou (poate de data asta e muștar)"}},"order402":{"title":"Comandă 100 de Mici","subtitle":"Un buton. O comandă. Un colaps complet al sistemului nervos al CFO-ului.","button":"COMANDĂ 100 DE MICI!","errorTitle":"ERROR 402 — PAYMENT REQUIRED!","errorSub":"Sistemul financiar NOXIS a fost notificat. Și prin „notificat” înțelegem „aprins”.","panic":["Nyxer: „O SUTĂ de mici?! Cine a aprobat asta?! CINE ARE BUGETUL?!\"","Nyxer: „Cărbune, carne, condimente, șervețele... se înmulțesc... cifrele SE ÎNMULȚESC!”","Nyxer: „Suntem un site de comedie, nu o firmă de catering!”"],"taraLine":"Tara: „Nyxer, respiră. E o simulare. Nimeni nu cumpără nimic.”","nyxerFinal":"Nyxer: „NICI MĂCAR MICII NU SUNT REALI?!\"","disclaimer":"Comedie pură: fără plăți reale, fără date bancare, fără mici comandați de fapt. Portofelul tău e în siguranță. Al lui Nyxer, nu.","again":"Comandă din nou (lui Nyxer îi place)"},"stress":{"title":"Nivelul de Stres al lui Nyxer","subtitle":"Indicator live al nervilor directorului financiar NOXIS. Fiecare eveniment de pe site îl hrănește. Savurează cu responsabilitate.","reasons":{"order":"Cineva a comandat 100 de mici gratis.","mustard":"Vânătoarea muștarului s-a încheiat. Borcanul era gol.","wrongSearch":"Încă o percheziție greșită în bucătărie.","chaosTara":"Tara a pornit un proiect nou-nouț.","chaosAren":"Aren a descoperit încă un skill pe GitHub.","chaosRobot":"Robotul a comandat mai multe ingrediente.","chaosNyra":"Nyra a cerut un meniu special.","chaosZ230":"Z230 a amenințat că se oprește.","nyraMenu":"Meniul special al lui Nyra a fost aprobat.","z230hot":"Z230 e periculos de aproape de topire."},"levels":{"calm":"Nyxer e calm. Suspicios de calm.","worried":"Nyxer își verifică facturile. Din nou.","panicked":"Nyxer aleargă între foi de calcul.","meltdown":"COLAPS TOTAL. Acoperiți calculatoarele!"},"shout":"13 PROIECTE! ZERO ÎNCASĂRI! ȘI ACUM NU AVEM NICI MUȘTAR!","chaos":"Provoacă haos aleatoriu","reset":"Dă-i o bere lui Nyxer 🍺","logTitle":"Ultimele incidente:","emptyLog":"Nu s-a întâmplat nimic încă. Nyxer nu are încredere.","afterReset":"Nyxer: „Sunt calm acum. Perfect de calm. Nu atingeți nimic.”"},"nyra":{"title":"Hrănește-o pe Nyra","subtitle":"Oferă preparate inspectoarei supreme. Acceptă unele, respinge majoritatea, judecă mereu.","foods":{"salmon":"Somon la grătar","chicken":"Pui simplu","egg":"Ou fiert","cheese":"Cub de cașcaval","shrimp":"Crevete","milk":"Lapte de vacă","onion":"Ceapă","garlic":"Usturoi","chocolate":"Ciocolată","grapes":"Struguri"},"offer":"Oferă","accepted":["Miau. Acceptabil. Pentru un om.","Nyra gustă. Încet. „Am avut mai bine. Adaugă-l la dosarul meu.”","„Comestibil. Servirea rămâne groaznică.”"],"disdain":["Nyra privește farfuria. Apoi pe tine. Apoi iar farfuria. „Nu.”","„Miau. Eu inspectez restaurante. Nu mănânc greșelile lor.”","O miroase o dată și pleacă cu dezamăgire regală."],"reject":["„{food}?! Încerci să otrăvești inspectoarea?! E TOXIC pentru pisici!”","„Absolut nu. {food} e periculos pentru feline. O stea. Dacă aș putea da zero, aș da.”","„{food} — respins. Mustățile mele detectează pericol. Și prost gust.”"],"specialMenu":"Nyra și-a compus meniul special.","nyxerQuestion":"Nyxer: „Stai... cât costă meniul special?”","nyraAnswer":"Nyra: „Miau. Pune-l pe factura ta!”","vetNote":"Joc de comedie — în viața reală, nu hrăni pisicile cu mâncare de grătar. Ceapa, usturoiul, ciocolata și strugurii sunt toxice pentru pisici. Îndoieli? Întreabă veterinarul.","unsafeLabel":"Periculos pentru pisici","safeLabel":"Sigur pentru pisici (în joc)"},"z230":{"title":"Z230 — Melcul Supraîncălzit","subtitle":"Calculatorul bătrân al familiei privește grătarul cu groază. Pornește BBQ-ul și vezi cât rezistă.","start":"PORNEȘTE GRĂTARUL!","stop":"Răcorește (salvează melcul)","react":"Z230: „NU PE PROCESORUL MEU!”","lines":{"warm":["Z230: „Se încălzește aici sau doar mi se pare mie?”","Z230: „Deschid toate ventilatoarele. Toate. Adică două.”"],"hot":["Z230: „Sunt oficial o fondue de melc. Nu e metaforă.”","Z230: „Dacă mă îngheț acum, spuneți fișierelor mele că le-am iubit.”"],"critical":["Z230: „URGENȚĂ! Sunt la un grad distanță de a deveni melc la grătar!”","Z230: „Mă opresc în 3... 2... dacă nu mă răcoriți cineva ACUM!”"]},"tempLabel":"Temperatura comică","disclaimer":"Unitățile sunt 100% comedie (°SN — Unități Melc). Acest termometru nu măsoară nimic real.","shutdown":"Z230 leșină dramatic. O să fie bine. Mereu o să fie."},"wall":{"title":"NOXIS BBQ — Zidul Comediei","subtitle":"Lasă o glumă, un comentariu, o mărturisire de grătar. În orice limbă. Nyra oricum o va judeca.","nickname":"Pseudonim","nicknamePh":"ex. MuștaruFan42","comment":"Comentariu","commentPh":"Cea mai amuzantă poveste cu grătar...","post":"Publică comentariul","reply":"Răspunde","replyPh":"Răspunsul tău...","cancelReply":"Anulează","like":"Apreciază","deleted":"Comentariu șters de moderator. Nyra a aprobat.","adminMode":"Mod moderator","adminPassword":"Parola de moderator","adminLogin":"Autentificare","adminLogout":"Deconectare","delete":"Șterge","wrongPassword":"Parolă greșită. Nyra te privește.","moderatorOn":"Mod moderator ACTIVAT.","moderatorOff":"Mod moderator dezactivat.","empty":"Zidul e gol. Fii prima legendă!","loading":"Se încarcă comedia...","postedOk":"Comentariu publicat! Familia NOXIS te salută.","spamFast":"Ușurel, legendă! Prea multe comentarii prea repede. Încearcă într-un minut.","spamBlocked":"Melcul anti-spam NOXIS a blocat mesajul. Încearcă altceva.","badContent":"Nyra a respins comentariul. Fii prietenos și amuzant!","nicknameBad":"Pseudonimul are nevoie de 2-24 de caractere. Ca orice legendă.","commentBad":"Comentariul are nevoie de 2-500 de caractere.","demoNotice":"Fără cont, fără înregistrare: scrii, publici, râzi. Comentariul și pseudonimul tău sunt vizibile tuturor vizitatorilor; adresa IP este folosită exclusiv pentru protecția anti-spam și nu este afișată niciodată.","translate":"Tradu","translating":"Se traduce...","translateNote":"Traducere AI (serviciu real, poate fi imperfectă).","translateError":"Serviciul de traducere nu e disponibil acum. (Probabil Nyra l-a deconectat.) Comentariul rămâne în limba originală — aici nu se prezintă traduceri fictive.","translateFast":"Mașina de tradus se răcorește. Încearcă din nou în câteva secunde.","offlineTitle":"Comentariile publice au nevoie de un server","offlineBody":"Această versiune NOXIS BBQ rulează direct în interiorul NOXIS UNIVERS, fără server. Comentariile publice, răspunsurile, like-urile, traducerea AI și moderarea funcționează doar în versiunea completă Next.js cu backend (vezi INTEGRARE.md). Aici nu se simulează nimic — Nyra nu tolerează falsurile.","offlineHint":"📍 Notă locală pentru UNIVERS — aceasta NU este o secțiune de comentarii publice.","backendDoc":"Documentul BACKEND-NECESAR.md din arhivă descrie tot ce e nevoie; versiunea Next.js completă (noxis-bbq-complete.zip) are deja backend-ul gata construit.","rules":"Fii amuzant, fii prietenos. Fără date personale. Melcul modulează."},"music":{"welcomeTitle":"BUN VENIT LA NOXIS BBQ!","welcomeSub":"100 de mici. Un muștar dispărut. Haos infinit!","enterMusic":"🎸 INTRĂ ÎN NOXIS BBQ — DA MUZICA MAI TARE!","enterSilent":"🔇 INTRĂ FĂRĂ MUZICĂ","play":"Redă","pause":"Pauză","mute":"Fără sunet","unmute":"Cu sunet","volume":"Volum","nowPlaying":"Redă acum","credits":"TARA NOXIS — WHERE'S THE MUSTARD?! · Muzică © Tara Noxis"},"comandamente":{"title":"Cele 10 Comandamente ale Grătarului","subtitle":"Scrise în fum pe o tablă de inox, descoperite lângă grătarul bunicii.","items":[{"title":"Să nu grătești niciodată flămând","text":"Vei mânca carne crudă din disperare și te vei minți singur că „așa se face la noi”. Rezistă, erou. Măcar o felie de pâine înainte."},{"title":"Onorează muștarul, căci el te va ridica","text":"Muștarul nu e condiment. E religie. Cine mănâncă mici fără muștar riscă excluderea din bresla grătaristilor și priviri judecătoare de la bunici."},{"title":"Nu uita sarea!","text":"Zeul grătarului nu iartă carnea fade. Carnea fără sare e ca gluma fără punct culminant: există, dar nu aduce bucurie."},{"title":"Păzește grătarul cu viața ta","text":"Câinii vecinului pândesc. Pisicile fac misto. Iar unchiul Gheorghe „doar se uită” din 2009. Stai aproape. Mereu."},{"title":"Fumul în ochi e botezul grătaristului adevărat","text":"Dacă nu ai plâns măcar o dată la grătar, nu ai trăit. Lacrimile de la fum NU sunt emoții. Sunt certificat de grătarist adevărat."},{"title":"Nu măsura câți mici ai mâncat","text":"Măsoară doar cât de fericit ești. Numărul micilor e subiect controversat și nu trebuie discutat cu partenerul/a sau cu medicul."},{"title":"Focul mic e pentru codași, focul mare e pentru eroi","text":"Cu măsură, totuși. Nu vrem să chemăm pompierii la al treilea mic. Anul trecut a fost accident. Anul acesta a fost „experiment”."},{"title":"Cine aduce berea rece va fi binecuvântat","text":"În vecii vecilor, berea rece e stea de pe cerul grătarului. Cine aduce berea caldă va fi rugat blând să o țină în mâini până se răcește."},{"title":"Nu întreba „e gata?”","text":"Grătarul știe singur când e gata. Întrebarea „e gata?” repetată de 40 de ori nu grăbește procesul, ci doar stresează carnea. Carnea are și ea sentimente."},{"title":"Iubește-ți vecinul, dar nu-i da primul mic","text":"Reguli sunt reguli. Primul mic aparține grătaristului. E a treia lege a dinamicii grătarului. Noi n-am inventat-o. Doar ne supunem."}]},"tipuri":{"title":"Cele 6 Tipuri de Grătari","subtitle":"Toți i-ai întâlnit. Toți există. Poate ești chiar tu. (Dacă ești Experimentatorul, te rugăm frumos: nu.)","items":[{"name":"Artistul","motto":"„Fiecare mic e o operă de artă.”","desc":"Prezintă carnea ca pe o expoziție la bienală. Fotografiază fiecare mic de 15 ori, din 9 unghiuri, înainte să-l mănânce. Apoi carnea s-a răcit. Nu-i pasă. Artă.","level":"Nivel: Louvre-ul curții"},{"name":"Filosoful","motto":"„Dar ce e, de fapt, un mic?”","desc":"Stă 3 ore la grătar și vorbește despre sensul vieții, universului și a tot ceea ce e. Între timp, carnea arde. „Fumul e metaforă”, zice el, în timp ce alarma de fum e de acord.","level":"Nivel: Zen în flăcări"},{"name":"Ninja","motto":"„Ai văzut vreodată un ninja spălând farfurii? Exact.”","desc":"Apare exact când carnea e gata. Dispare exact când trebuie spălate farfuriile. Nimeni nu l-a văzut vreodată ducând cărbuni. Legendele urbane spun că există, dar nimeni nu poate confirma.","level":"Nivel: invizibil, dar hrănit"},{"name":"Planificatorul","motto":"„Am făcut un Excel. Aveți 5 minute să-l citiți.”","desc":"Are un spreadsheet cu micii pe persoană, prognoza meteo pe 48 de ore, grafic cu timpii de gătire și plan de evacuare. Grătarul lui pornește la secundă. Precis. Înfricoșător.","level":"Nivel: NASA de curte"},{"name":"Experimentatorul","motto":"„Dar dacă am pune... ananas?”","desc":"Pune ananas la grătar. ANANAS. La. Grătar. Apoi încearcă mici cu ciocolată „pentru știință”. Comunitatea îl veghează îndeaproape. Robotul Bucătar a depus deja o plângere formală.","level":"Nivel: laborator interzis"},{"name":"Veteranul","motto":"„Grătesc din '87. Nu accept critici.”","desc":"Carnea lui e mereu „perfectă”, chiar și când e carbonizată la nivel molecular. Are opinii tari despre cărbune, lemn, foc și viață în general. Nu se contrazice. Nu se mai încearcă.","level":"Nivel: general în retragere"}]},"miciometru":{"title":"Mici-O-Metrul 3000","subtitle":"Dispozitiv medical de ultimă generație care măsoară câți mici poți mânca. Precizie: ±0 mici. Doar apasă și vezi cât de departe ajungi!","counterLabel":"Contor de mici consumați","unit":"mici devorați cu onoare","eat":"Mănâncă un mic!","reset":"Reset (medicul a sunat)","rangs":["Amator","Grătarist-Major","Legendă"],"legendTarget":"Legendă","milestones":["Începe, curajule! Măcar un mic. Robotul te privește așteptător. 🤖","Leneș! Chiar și robotul mănâncă mai mult. Și el nu are stomac! 🤖","A ÎNCEPUT! Bunicii încet-încet își schimbă părerea despre tine.","Respectabil! Deja vorbești cu accent ardelenesc. Nu știu cum, dar e frumos.","MARE! Bunica plânge de mândrie. Sau de la fum. Greu de spus.","AI AJUNS la rangul de GRĂTARIST-MAJOR! Mai sunt doar 30 de ranguri până la Legendă.","Wow. Doar wow. Cineva aduce deja al doilea borcan de muștar. E serios.","LEGENĂ ÎN CONSTRUCȚIE! Vecinii încep să se adune. Cineva a adus porțelan de la serviciu.","LEGENĂ CONFIRMATĂ! Trebuie să fii neapărat din Ardeal sau dintr-o familie de campioni.","AI DEPĂȘIT LIMITELE UMANE! Chemăm robotul să te oprească. Și el mănâncă mult, deci e grav. 🤖🚨"],"disclaimer":"* Mici-O-Metrul nu acceptă răspundere pentru indigestie, somn după prânz sau vise cu grătare care fug."},"quiz":{"title":"Quiz: Ce Fel de Grătar Ești?","subtitle":"Patru întrebări. Un destin. Zero răspunsuri greșite (doar răspunsuri delicioase).","qOf":"Întrebarea","of":"din","restart":"Refac quiz-ul, poate merg mai bine 🔁","ghost":"(Ai răspuns de 0 ori? Grătarist fantomă? Impresionant.) 👻","resultTitle":"Rezultatul tău e...","questions":[{"q":"Ce faci când cineva susține că altcineva face grătar mai bun?","a":["„Interesantă teorie. Ai studiat subiectul? Ți-am pregătit un document de 40 de pagini.”","„Fiecare are propriul drum spre iluminare. Să nu judecăm.”","„Zâmbești politicos, dar în suflet te-ai înscris deja la duel.”"]},{"q":"Când e momentul perfect să aprinzi grătarul?","a":["„14:00 fix. Am notat. Am recalculat. Am plan de rezervă.”","„Când inima îți strigă: FOARTE SOMNOROS, DAR ȘI FOAME.”","„Când lumina cade la 45 de grade și cerul e albastru Picasso.”"]},{"q":"Care e secretul unui mic perfect?","a":["„Răbdare, iubire și un pic de fum în ochi.”","„Să nu-l arzi. Restul sunt doar detalii de care nu am auzit.”","„Rețeta secretă de familie. Din 1987. Nu o spun nici sub tortură.”"]},{"q":"Un invitat aduce ananas la grătar. Reacția ta?","a":["„Interesant. Îl pun lângă carne, dar doar pentru știință.”","„Fotografiez ananasul din 9 unghiuri înainte să respire cineva.”","„Apar din umbră și îl confisc discret. Niciodată nu mă vede nimeni.”"]}],"results":{"Philosopher":{"name":"Grătarist Filosof","desc":"Tu și grătarul sunteți un singur suflet. Vorbești despre sensul vieții în timp ce carnea se face singură (de obicei în flăcări). Ești înțelept, calm și singurul care își amintește de ce a fost pornit focul."},"Artist":{"name":"Grătarist Artist","desc":"Pentru tine, grătarul e galerie, farfuria e ramă, iar muștarul e pensulă. Fiecare mic e fotografiat, filtrat și prezentat. Carnea s-a răcit? Nu-i nimic. Contente-ul e tot."},"Ninja":{"name":"Grătarist Ninja","desc":"Nimeni nu știe de unde vii, nimeni nu știe unde te duci. Apari la grătar exact când carnea e gata și dispare când se strâng farfuriile. Ești o legendă urbană hrănită cu mici."},"Planner":{"name":"Grătarist Planificator","desc":"Grătarul tău e o operațiune militară. Ai Excel cu micii pe persoană, prognoze meteo și planuri B, C și D. Nimic nu merge prost. Nimic. Niciodată. (Până acum.)"},"Experimenter":{"name":"Grătarist Experimentator","desc":"Pentru tine, grătarul e laborator. Mici cu ciocolată? Da. Ananas la grătar? DA. Comunitatea te veghează, dar recunoaște: uneori, uneori, ai dreptate. Foarte rar. Foarte."},"Veteran":{"name":"Grătarist Veteran","desc":"Grătești din generații. Carnea ta e mereu „perfectă”, focul tău e mereu „corect”, iar opiniile tale despre cărbune sunt legi. Nu se contrazice veteranul. Nu se mai încearcă."}}},"scuze":{"title":"Generatorul de Scuze pentru Grătar","subtitle":"Prietenii te cheamă la nuntă? La teatru? La „o plimbare sănătoasă”? Nu-ți face griji — avem scuze de nivel mondial, testate pe soacre.","placeholder":"Apasă butonul și primești o scuză solidă, verificată legal de Robotul Bucătar. 🤖","generate":"Generează scuză!","counter":"Scuze generate până acum","legend":" — cazi grav pe lista de invitați, dar ești Legenda grătarului! 🏆","items":["„Nu pot veni azi. Micii cer atenție. E o problemă de relație.”","„Medicul mi-a interzis grătarul... al altora. Al meu e prescris medical.”","„Am o întâlnire importantă: grătarul și mine. 14:00. În curte. Nu se amână.”","„Cineva trebuie să păzească carnea de curioși. Am făcut voluntariat. Sunt erou.”","„Mașina nu pornește. Și nici nu vrea. Simte fumul de la grătar și refuză să plece.”","„Sunt alergic la zilele fără grătar. E grav. Doctorii sunt confuzi.”","„Nu pot zbura azi, dar pot să grătesc. Aproape la fel, doar mai delicios.”","„Boss-ul mi-a dat liber pentru «afaceri importante». Micii SUNT afacerea.”","„Am promis soacrei că vin... la grătar. Nu am zis unde stau. Bucățica legală.”","„Azi nu pot. Dar cine va testa calitatea cărnii? Eu. Exact. Suntem o echipă.”","„Azi nu pot. Carnea are nevoie de mine emoțional. Și eu de ea. E reciproc.”","„Mi-am luxat glezna. Încercând să-i pun papuci de sport grătarului. Poveste lungă.”","„Trebuie să stau acasă. WiFi-ul mă așteaptă. Și grătarul de la etaj. Și frigiderul.”","„Sunt în antrenament pentru Maratonul Micilor. Nu pot întrerupe. Sunt la micul 4 din 40.”","„Sunt alergic la fum, funingine și zile fără grătar. Doctorii sunt perplexi. Eu m-am împăcat.”"]},"dictionar":{"title":"Dicționarul Grătaristului","subtitle":"Termeni oficiali, definiții legale (nu chiar), aprobate de Academia Fumatului de Curte.","items":[{"term":"mic (substantiv)","phonetic":"/mik/","def":"Unitatea fundamentală de măsură a fericirii. 1 mic = 7 unități de bucurie standardizate. Se servește obligatoriu cu muștar și povești. Plural: mici (fericire multiplă)."},{"term":"muștar (substantiv)","phonetic":"/muș-tar/","def":"Lichidul sfânt al grătaristului. Nu e condiment — e sacrament. Se toarnă cu generozitate și cu credință. Cine folosește ketchup e rugat frumos să plece. (Pe jumătate glumim.)"},{"term":"fum (substantiv)","phonetic":"/fum/","def":"Parfumul oficial al zilelor de vară și principala cauză a salivării vecinilor. Se depistează pe haine luni mai târziu, ca amintire fidelă a unei zile perfecte."},{"term":"opportunivor (substantiv)","phonetic":"/op-por-tu-ni-vor/","def":"Persoana care vine la grătar exact când mâncarea e gata, fără să fi adus nimic. Identificare: mănâncă cu viteza luminii, dispare la spălat vase."},{"term":"ardei copt (substantiv)","phonetic":"/ar-dei/","def":"Cel mai bun prieten al micului. Se coace lent, cu demnitate, și își abandonează imediat pe oricine îl mănâncă fără pâine. E o relație complexă, dar frumoasă."},{"term":"„e gata?” (exprimare)","phonetic":"/e ga-ta/","def":"Întrebarea interzisă nr. 1 la grătar. Repetată de 40 de ori, nu grăbește carnea, dar stresează grătaristul. Alternativă: „mai e mult?” (interzisă nr. 2)."},{"term":"grătarist veteran (substantiv)","phonetic":"/ve-te-ran/","def":"Cel care grătește din 1987 și nu acceptă critici. Carnea lui e mereu „perfectă”, chiar și după starea de carbon. Respectul se impune prin fum."},{"term":"bere rece (substantiv)","phonetic":"/be-re re-ce/","def":"Stea de pe cerul grătarului. Cine aduce berea rece va fi binecuvântat în vecii vecilor. Cine aduce berea caldă o va ține în mâini, cu demnitate, până se răcește."}]},"footer":{"brand":"🍖 NOXIS BBQ 🍖","copyright":"© 2026 Universul NOXIS — Toți micii sunt respectați. Nicio carne nu a fost arsă intenționat în realizarea acestui site. (Doar puțin. De două ori.)","comedyNote":"Site de comedie. Definițiile, scuzele și rangurile sunt fictive. Micii, dimpotrivă, sunt foarte reali. Grătește responsabil!","musicCredit":"🎵 TARA NOXIS — WHERE'S THE MUSTARD?! · Muzică © Tara Noxis"}},
  "de": {"meta":{"title":"NOXIS BBQ — FEHLER 404: SENF NICHT GEFUNDEN! 🌭🔥","description":"Der Senf fehlt, der Roboter kocht, und Nyxer verliert den Verstand! Senf-Jagd, 100-Mici-Bestellung, Nyra die Inspektorin, Z230 die überhitzte Schnecke und die Comedy-Wand."},"nav":{"brand":"NOXIS BBQ","personaje":"NOXIS-Crew","mustard":"Senf-Jagd","order":"100 Mici","stress":"Nyxers Stress","nyra":"Nyra füttern","z230":"Z230","comandamente":"Gebote","tipuri":"Griller-Typen","miciometru":"Mici-O-Meter","quiz":"Quiz","scuze":"Ausreden","dictionar":"Wörterbuch","wall":"Comedy-Wand","langLabel":"Sprache","soundOn":"Ton an","soundOff":"Ton aus","menu":"Bereiche"},"hero":{"badge":"🔥 Die einzige Website, die nach Grill riecht 🔥","titleA":"NOXIS","titleB":"BBQ","tagline":"Wo der Senf fehlt, der Roboter kocht und Nyxer den Verstand verliert!","subtitle":"Eine interaktive Sci-Fi-Komödie: jage den verschwundenen Senf, bestelle 100 Mici (FEHLER 402!), füttere die Katzen-Inspektorin und rette den alten Z230 vor dem Schmelzen. Und ja — es gibt auch echte gegrillte Mici.","cta1":"Senf-Jagd starten 🏺","cta2":"100 Mici bestellen 🌭","footnote":"* Der Roboter auf dem Foto hat während des Shootings 47 Mici gegessen. Niemand hat ihn aufgehalten.","caption":"🤖 Chef-Roboter — der visuelle Star des NOXIS-Grills"},"seal":{"alt":"Das Siegel der Familie NOXIS","toast":"Das NOXIS-Siegel schnurret zustimmend. Die Familie beobachtet den Grill."},"generic":{"say":"Sag was!","reset":"Zurücksetzen","close":"Schließen","attempts":"Versuche"},"characters":{"title":"Die NOXIS-Crew","subtitle":"Eine Familie, ein Grill, null Senf. Klicke auf eine Figur und höre, was sie davon hält.","familyCta":"Fotos der NOXIS-Familie ansehen!","familyTitle":"Die NOXIS-Familie","familySubtitle":"Eine Familie. Ein Grill. Unendliches Chaos.","familyAlt":"Das offizielle NOXIS-Familienfoto — Tara, Nyxer, Nyxar, Nyxin, AR_ON, AR_IN und Aren","familyCaption":"Offizielles Familienporträt. Der Senf fehlt, aber die Liebe (und das Chaos) sind vollständig anwesend.","roles":{"tara":{"name":"TARA NOXIS","role":"Schöpferin des NOXIS-Universums","desc":"Erfinderisch, voller neuer Ideen. Sie startet Projekte, bevor Nyxer die Rechnung für das letzte fertig hat."},"nyxer":{"name":"NYXER NOXIS","role":"Finanzdirektor (voller Panik)","desc":"Hat Angst vor Ausgaben, Rechnungen und Projekten ohne Einnahmen. Reagiert dramatisch auf jede Bestellung — sogar auf einen Burger."},"aren":{"name":"AREN NOXIS","role":"Forscher & GitHub-Entdecker","desc":"Für jedes Problem findet er ein weiteres Open-Source-Tool. Die Repo-Zahl steigt schneller als die Grilltemperatur."},"nyra":{"name":"NYRA","role":"Oberste Restaurant-Inspektorin","desc":"Unabhängig, ironisch, anspruchsvoll. Hält sich für die höchste kulinarische Autorität im NOXIS-Universum. Pfoten inklusive."},"z230":{"name":"Z230","role":"Der alte Familiencomputer (als Schnecke)","desc":"Langsam, loyal, warmherzig. Lebt in Angst vor Überhitzung — und davor, dass jemand neue Software auf ihn installiert."},"robot":{"name":"KÜCHEN-ROBOTER","role":"Silberner Grillmeister","desc":"Freundlicher silberner Roboter mit leuchtend blauen Augen. Grillt Mici perfekt und sorgt ständig für absurde Situationen."},"aron":{"name":"AR_ON NOXIS","role":"Rechte & Lizenzen","desc":"Taucht aus dem Nichts auf, sobald jemand ein Bild ohne Erlaubnis benutzt. Sagt wenig. Seine Verträge kommen vor ihm an."},"nyxar":{"name":"NYXAR NOXIS","role":"Systemadministrator","desc":"Hält das ganze NOXIS-Universum online. Server, Firewall, Uptime — sein Königreich. Gelassen wie ein Sysadmin, der bereits ein Backup hat. Von allem. Zweimal."},"arin":{"name":"AR_IN NOXIS","role":"Hüterin der Geschichten","desc":"Erzählen. Schreiben. Erinnern. Sie dokumentiert jede Grill-Katastrophe für die Nachwelt — in elegantem Eisblau."},"nyxin":{"name":"NYXIN NOXIS","role":"Visuelle Kreation","desc":"Zeichnen. Gestalten. Erinnern. Jeder Pixel des NOXIS-Universums entsteht in ihren Händen — manchmal sogar während eines Nickerchens. Es sieht einfach perfekt aus."}},"dialogues":{"tara":["Moment, ich habe eine Idee für ein WEITERES Projekt!","Das Senf-Verschwinden? Inspirierend. Sehr inspirierend.","Ich habe 100 Mici bestellt. Finanziell? Das erklärt Nyxer."],"nyxer":["WER HAT GELD AUSGEGEBEN?! WER?! ZEIGT MIR DEN BELEG!","13 Projekte! NULL Einnahmen! Und jetzt ist auch noch der Senf weg!","Ich gerate nicht in Panik. Ich... budgetiere aggressiv."],"aren":["Ich habe auf GitHub einen Open-Source-Senf-Detektor gefunden!","Dafür gibt's ein Repo. Es gibt IMMER ein Repo dafür.","Ich habe 14 neue Tools installiert. Die Lösung ist in einem davon. Wahrscheinlich."],"nyra":["Miau. Ich weiß, wo der Senf ist. Aber Information kostet.","Deine Grilltechnik? Zwei Pfoten nach unten.","Ich habe die Küche inspiziert. Bestanden. Knapp. Wegen mir."],"z230":["Wenn ihr noch etwas auf mir installiert, werde ich zu einer gegrillten Schnecke!","Wird geladen... langsam... wie immer... gebt mir... eine Minute...","Meine Lüfter singen. Das ist kein gutes Zeichen."],"robot":["Ich habe 100 Mici zubereitet. Der Senf ist nicht im Inventar!","Grill-Level: Perfektion. Senf-Level: FEHLER 404.","Ich esse nicht. Ich koche nur. Für alle anderen ist das eine Tragödie."],"aron":["Das Feuer hat zu mir gesprochen. Es sagte: mehr Holzkohle.","Ich jage den Senf nicht. Der Senf jagt mich.","Dunkelheit, Stille... und der Geruch von Mici. Perfekt."],"nyxar":["Schon versucht, den Grill aus- und wieder einzuschalten?","Ich habe keine Probleme. Ich habe Tickets. Und alle sind geschlossen.","Der Senf ist nicht in der Datenbank. Ich habe nachgesehen. Zweimal. Mit JOINs."],"arin":["Tag 1 der Senf-Krise. Ich schreibe alles mit.","Jede Legende braucht einen Chronisten. Und jeder Grill einen Zeugen.","Erzählen. Schreiben. Erinnern. Besonders den Teil, wo das Glas verschwand."],"nyxin":["Ich habe geträumt, die Website funktioniert. Dann bin ich aufgewacht — und sie tat es.","Ich habe den Bug im Schlaf repariert. Gern geschehen.","Du bist nicht verloren, du erschaffst gerade etwas. Übrigens: Der Senf ist im Kühlschrank."]}},"mustard":{"title":"Die Große Senf-Jagd","subtitle":"Die Mici sind fertig. Der Senf ist verschwunden. Durchsuche die NOXIS-Küche und finde das Glas — folge den Hinweisen!","errorTitle":"FEHLER 404 — SENF NICHT GEFUNDEN!","robotAnnounce":"Chef-Roboter verkündet: Die Mici sind fertig... aber der Senf ist NICHT im Inventar!","start":"Suche starten!","searchHint":"Klicke (oder drücke Enter) auf ein Objekt, um es zu durchsuchen.","attemptsLabel":"Durchsuchungen","spots":["Kühlschrank","Oberschrank","Unterschrank","Backofen","Mikrowelle","Gewürzregal","Keksdose","Unter der Spüle","Speisekammer","Mülleimer","Werkzeugkasten","Weihnachtsdeko-Karton"],"cluesNear":["Es ist warm hier... der Senf ist NAH!","Nyra riecht Senf in der Nähe. Aber sie sagt nichts.","Die Löffelschublade zittert. Er muss nah sein!"],"cluesFar":["Nichts hier. Der Senf ist WEIT weg von dieser Stelle.","Z230 hat den Bereich gescannt: Senf-Wahrscheinlichkeit 3%. Such woanders.","Kalt. Kälter als Nyxers Reaktion auf die Rechnungen dieses Monats."],"decoys":[{"title":"Eine Ketchupflasche!","text":"Es ist Ketchup. KETCHUP. Nyra ist beleidigt, dass du sie überhaupt angefasst hast."},{"title":"Eine verlorene Socke...","text":"Warum liegt eine Socke in der Küche? Die Familie NOXIS hat Fragen. Keine Antworten."},{"title":"Nyras Lieblingsspielzeug!","text":"Eine kleine Plüschmaus. Du legst sie sehr, sehr vorsichtig zurück."}],"reactions":{"robot":["Senf immer noch verschwunden. Rechne Rezepte ohne ihn neu. Traurigkeits-Level steigt.","Ich habe mein Inventar zweimal geprüft. Das Glas weigert sich zu existieren."],"nyxer":["WER HAT 100 MICI OHNE SENF GEKAUFT?!","Weißt du, was Senf jetzt kostet?! Egal — WIR HABEN KEINEN!"],"aren":["Ich habe auf GitHub einen Open-Source-Senf-Detektor gefunden! Er braucht 14 Abhängigkeiten.","Neues Repo entdeckt: 'mustard-tracker-9000'. Letzter Commit: vor 3 Jahren. Perfekt."],"nyra":["Miau. Ich weiß genau, wo er ist. Aber Information kostet.","Amateure. Ich hätte ihn in 3 Sekunden gefunden. Mit geschlossenen Augen. Aus Prinzip."],"z230":["Wenn ihr noch eine Senf-Scan-App auf mich installiert, werde ich zu einer gegrillten Schnecke!","Scanne... langsam... die... Küche... habt... Geduld..."],"tara":["Sucht besser! Inzwischen habe ich eine Idee für ein anderes Projekt!","Die Senf-Krise hat mich inspiriert. Ich entwerfe einen Senf-Themenpark."],"aron":["Ich spüre... ein Glas. Oder einen Schatten. Eher einen Schatten.","Die Dunkelheit verbirgt vieles. Auch Senf. Leider."],"nyxar":["Ich habe einen Senf-Suchdienst bereitgestellt. Uptime: 100 %. Gefundene Gläser: 0.","Die Server-Logs sagen, Nyra hat das Glas genommen. Ich urteile nicht. Ich logge nur."]},"win":{"title":"SENF GEFUNDEN! ...oder etwa nicht?","found":"Du hast das Glas gefunden! Von absolut niemandem versteckt, für alle sichtbar.","empty":"Du öffnest es langsam... ES IST LEER.","robotConfession":"Chef-Roboter gesteht: „Ich habe den letzten Tropfen Senf für die 100 Mici benutzt. Meine Logikschaltkreise bereuen nichts.”","nyraLine":"Nyra: „Miau. Ich wusste es die ganze Zeit. Information kostet, erinnerst du dich?”","again":"Nochmal jagen (vielleicht gibt's diesmal Senf)"}},"order402":{"title":"100 Mici bestellen","subtitle":"Ein Button. Eine Bestellung. Ein kompletter Nervenzusammenbruch des CFO.","button":"100 MICI BESTELLEN!","errorTitle":"FEHLER 402 — BEZAHLUNG ERFORDERLICH!","errorSub":"Das NOXIS-Finanzsystem wurde benachrichtigt. Mit „benachrichtigt” meinen wir „angezündet”.","panic":["Nyxer: „HUNDERT Mici?! Wer hat das genehmigt?! WER HAT DAS BUDGET?!\"","Nyxer: „Holzkohle, Fleisch, Gewürze, Servietten... sie multiplizieren sich... die Zahlen MULTIPLIZIEREN SICH!”","Nyxer: „Wir sind eine Comedy-Website, kein Catering-Unternehmen!”"],"taraLine":"Tara: „Nyxer, atme. Es ist eine Simulation. Niemand kauft etwas.”","nyxerFinal":"Nyxer: „NICHT MAL DIE MICI SIND ECHT?!\"","disclaimer":"Reine Komödie: keine echten Zahlungen, keine Bankdaten, keine tatsächlich bestellten Mici. Deine Brieftasche ist sicher. Nyxers nicht.","again":"Nochmal bestellen (Nyxer liebt das)"},"stress":{"title":"Nyxers Stress-Level","subtitle":"Live-Messgerät für die Nerven des NOXIS-Finanzdirektors. Jedes Event auf dieser Website füttert es. In Maßen genießen.","reasons":{"order":"Jemand hat 100 Mici gratis bestellt.","mustard":"Die Senf-Jagd ist vorbei. Das Glas war leer.","wrongSearch":"Wieder eine vergebliche Suche in der Küche.","chaosTara":"Tara hat ein nagelneues Projekt gestartet.","chaosAren":"Aren hat schon wieder einen Skill auf GitHub entdeckt.","chaosRobot":"Der Roboter hat mehr Zutaten bestellt.","chaosNyra":"Nyra hat ein Spezialmenü verlangt.","chaosZ230":"Z230 hat mit Abschalten gedroht.","nyraMenu":"Nyras Spezialmenü wurde genehmigt.","z230hot":"Z230 ist gefährlich nah am Schmelzen."},"levels":{"calm":"Nyxer ist ruhig. Verdächtig ruhig.","worried":"Nyxer prüft Rechnungen. Wieder.","panicked":"Nyxer rast zwischen Tabellen hin und her.","meltdown":"TOTALE SCHMELZKRITIK. Deckt die Taschenrechner ab!"},"shout":"13 PROJEKTE! NULL EINNAHMEN! UND JETZT HABEN WIR AUCH NOCH KEINEN SENF!","chaos":"Zufälliges Chaos verursachen","reset":"Gib Nyxer ein Bier 🍺","logTitle":"Neueste Vorfälle:","emptyLog":"Noch ist nichts passiert. Nyxer traut der Sache nicht.","afterReset":"Nyxer: „Ich bin jetzt ruhig. Völlig ruhig. Fasst nichts an.”"},"nyra":{"title":"Nyra füttern","subtitle":"Biete der obersten Inspektorin Gerichte an. Sie akzeptiert einige, lehnt die meisten ab und urteilt immer.","foods":{"salmon":"Gegrillter Lachs","chicken":"Einfaches Huhn","egg":"gekochtes Ei","cheese":"Käsewürfel","shrimp":"Garnele","milk":"Kuhmilch","onion":"Zwiebel","garlic":"Knoblauch","chocolate":"Schokolade","grapes":"Trauben"},"offer":"Anbieten","accepted":["Miau. Akzeptabel. Für einen Menschen.","Nyra probiert. Langsam. „Ich hatte schon besseres. Ab in meine Akte.”","„Essbar. Der Service ist trotzdem schrecklich.”"],"disdain":["Nyra schaut das Gericht an. Dann dich. Dann das Gericht. „Nein.”","„Miau. Ich inspiziere Restaurants. Ich esse nicht ihre Fehler.”","Sie schnuppert einmal und geht mit königlicher Enttäuschung davon."],"reject":["„{food}?! Willst du die Inspektorin vergiften?! Das ist für Katzen GIFTIG!”","„Absolut nicht. {food} ist für Katzen gefährlich. Ein Stern. Wenn ich null geben könnte, würde ich.”","„{food} — abgelehnt. Meine Schnurrhaare erkennen Gefahr. Und schlechten Geschmack.”"],"specialMenu":"Nyra hat ihr Spezialmenü zusammengestellt.","nyxerQuestion":"Nyxer: „Moment... wie viel KOSTET das Spezialmenü?”","nyraAnswer":"Nyra: „Miau. Setz es auf DEINE Rechnung!”","vetNote":"Comedy-Spiel — im echten Leben füttere Katzen niemals mit Grillessen. Zwiebeln, Knoblauch, Schokolade und Trauben sind für Katzen giftig. Im Zweifel: Tierarzt fragen.","unsafeLabel":"Gefährlich für Katzen","safeLabel":"Katzenfreundlich (im Spiel)"},"z230":{"title":"Z230 — Die überhitzte Schnecke","subtitle":"Der alte Familiencomputer betrachtet den Grill mit Entsetzen. Starte das BBQ und sieh, wie lange er durchhält.","start":"GRILL STARTEN!","stop":"Abkühlen (rette die Schnecke)","react":"Z230: „NICHT AUF MEINEM PROZESSOR!”","lines":{"warm":["Z230: „Wird es hier warm, oder liegt das an mir?”","Z230: „Ich öffne alle meine Lüfter. Alle. Also zwei.”"],"hot":["Z230: „Ich bin offiziell eine Schnecken-Fondue. Das ist keine Metapher.”","Z230: „Wenn ich jetzt einfriere, sagt meinen Dateien, dass ich sie geliebt habe.”"],"critical":["Z230: „NOTFALL! Ich bin einen Grad davon entfernt, eine gegrillte Schnecke zu werden!”","Z230: „Ich schalte ab in 3... 2... außer jemand kühlt mich JETZT runter!”"]},"tempLabel":"Comic-Temperatur","disclaimer":"Die Einheiten sind 100% Komödie (°SN — Schnecken-Einheiten). Dieses Thermometer misst absolut nichts Reales.","shutdown":"Z230 ist dramatisch umgekippt. Er wird okay sein. Ist er immer."},"wall":{"title":"NOXIS BBQ — Comedy-Wand","subtitle":"Hinterlass einen Witz, einen Kommentar, ein Grillgeständnis. In jeder Sprache. Nyra urteilt sowieso.","nickname":"Spitzname","nicknamePh":"z.B. SenfFan42","comment":"Kommentar","commentPh":"Deine lustigste Grillgeschichte...","post":"Kommentar posten","reply":"Antworten","replyPh":"Deine Antwort...","cancelReply":"Abbrechen","like":"Gefällt mir","deleted":"Kommentar vom Moderator entfernt. Nyra hat zugestimmt.","adminMode":"Moderatoren-Modus","adminPassword":"Moderatoren-Passwort","adminLogin":"Anmelden","adminLogout":"Abmelden","delete":"Löschen","wrongPassword":"Falsches Passwort. Nyra beobachtet dich.","moderatorOn":"Moderatoren-Modus AN.","moderatorOff":"Moderatoren-Modus aus.","empty":"Die Wand ist leer. Sei die erste Legende!","loading":"Comedy wird geladen...","postedOk":"Kommentar gepostet! Die NOXIS-Familie grüßt dich.","spamFast":"Langsam, Legende! Zu viele Kommentare zu schnell. Versuch es in einer Minute.","spamBlocked":"Die NOXIS-Anti-Spam-Schnecke hat das blockiert. Versuch was anderes.","badContent":"Nyra hat deinen Kommentar abgelehnt. Bleib freundlich und lustig!","nicknameBad":"Der Spitzname braucht 2-24 Zeichen. Wie eine echte Legende.","commentBad":"Der Kommentar braucht 2-500 Zeichen.","demoNotice":"Kein Konto, keine Anmeldung: tippen, posten, lachen. Dein Spitzname und dein Kommentar sind für alle Besucher sichtbar; die IP-Adresse wird ausschließlich zum Spamschutz verwendet und nie angezeigt.","translate":"Übersetzen","translating":"Übersetze...","translateNote":"KI-Übersetzung (echter Service, kann unvollkommen sein).","translateError":"Der Übersetzungsdienst ist gerade nicht verfügbar. (Nyra hat ihn vermutlich ausgesteckt.) Der Kommentar bleibt in der Originalsprache — hier gibt es keine erfundenen Übersetzungen.","translateFast":"Die Übersetzungsmaschine kühlt sich ab. Versuche es in ein paar Sekunden erneut.","offlineTitle":"Öffentliche Kommentare brauchen einen Server","offlineBody":"Diese NOXIS-BBQ-Version läuft direkt in NOXIS UNIVERS, ohne Server. Öffentliche Kommentare, Antworten, Likes, KI-Übersetzung und Moderation funktionieren nur in der vollständigen Next.js-Version mit Backend (siehe INTEGRARE.md). Hier wird nichts simuliert — Nyra toleriert keine Fälschungen.","offlineHint":"📍 Lokale Notiz für UNIVERS — dies ist KEINE öffentliche Kommentar-Sektion.","backendDoc":"Die Datei BACKEND-NECESAR.md im Archiv beschreibt alles Nötige; die vollständige Next.js-Version (noxis-bbq-complete.zip) bringt ein fertiges Backend mit.","rules":"Sei lustig, sei nett. Keine persönlichen Daten. Die Schnecke moderiert."},"music":{"welcomeTitle":"WILLKOMMEN BEI NOXIS BBQ!","welcomeSub":"100 Mici. Ein verschwundener Senf. Unendliches Chaos!","enterMusic":"🎸 NOXIS BBQ BETRETEN — MUSIK AUFDREHEN!","enterSilent":"🔇 OHNE MUSIK EINTRETEN","play":"Abspielen","pause":"Pause","mute":"Stumm schalten","unmute":"Ton einschalten","volume":"Lautstärke","nowPlaying":"Läuft gerade","credits":"TARA NOXIS — WHERE'S THE MUSTARD?! · Musik © Tara Noxis"},"comandamente":{"title":"Die 10 Gebote des Grillens","subtitle":"In Rauch auf eine Edelstahltafel geschrieben, neben Omas Grill gefunden.","items":[{"title":"Grille nie hungrig","text":"Du wirst rohes Fleisch aus Verzweiflung essen und dich selbst überzeugen, dass „das hier so läuft”. Halte durch, Held. Zuerst mindestens eine Scheibe Brot."},{"title":"Ehre den Senf, denn er wird dich erhöhen","text":"Senf ist kein Gewürz. Es ist eine Religion. Wer Mici ohne Senf isst, riskiert den Ausschluss aus der Grillzunft und wertende Blicke von Oma."},{"title":"Vergiss das Salz nicht!","text":"Der Grillgott vergibt fades Fleisch nicht. Fleisch ohne Salz ist wie ein Witz ohne Pointe: Er existiert, aber er bringt keine Freude."},{"title":"Bewege den Grill mit deinem Leben","text":"Die Hunde der Nachbarn lauern. Die Katzen höhnen. Und Onkel Gheorghe „schaut nur” seit 2009. Bleib nah. Immer."},{"title":"Rauch in den Augen ist die Taufe eines wahren Grillers","text":"Wenn du am Grill nie geweint hast, hast du nicht gelebt. Rauchtränen zählen NICHT als Emotionen. Sie zählen als Zertifikat."},{"title":"Zähle die Mici nicht, die du gegessen hast","text":"Zähle nur, wie glücklich du bist. Die Mici-Zahl ist ein kontroverses Thema und darf nie mit Partner oder Arzt besprochen werden."},{"title":"Kleines Feuer für Anfänger, großes Feuer für Helden","text":"Mit Maß und Ziel allerdings. Wir wollen nicht wegen des dritten Mici die Feuerwehr rufen. Letztes Jahr war ein Unfall. Dieses Jahr war „ein Experiment”."},{"title":"Wer das kalte Bier bringt, sei gesegnet","text":"Von Ewigkeit zu Ewigkeit ist kalter Bier der Stern am Grillhimmel. Wer warmes Bier bringt, wird freundlich gebeten, es in den Händen zu halten, bis es kalt wird."},{"title":"Frag nicht „ist er fertig?”","text":"Der Grill weiß, wann er fertig ist. Vierzigmal „ist er fertig?” beschleunigt nichts — es stresset nur das Fleisch. Fleisch hat auch Gefühle."},{"title":"Liebe deinen Nächsten, aber gib ihm nie das erste Mici","text":"Regeln sind Regeln. Das erste Mici gehört dem Griller. Das ist das dritte Gesetz der Grilldynamik. Wir haben es nicht erfunden. Wir gehorchen nur."}]},"tipuri":{"title":"Die 6 Griller-Typen","subtitle":"Du hast sie alle getroffen. Sie existieren alle. Einer bist vielleicht du. (Wenn du der Experimentierer bist, bitte: nicht.)","items":[{"name":"Der Künstler","motto":"„Jedes Mici ist ein Kunstwerk.”","desc":"Präsentiert das Fleisch wie eine Biennale-Ausstellung. Fotografieren jedes Mici 15-mal, aus 9 Winkeln, bevor er es isst. Dann ist das Fleisch kalt. Ihm egal. Kunst.","level":"Level: Hof-Louvre"},{"name":"Der Philosoph","motto":"„Aber was IST ein Mici eigentlich?”","desc":"Verbringt 3 Stunden am Grill und spricht über den Sinn des Lebens, des Universums und des ganzen Restes. Zwischendurch verbrennt das Fleisch. „Der Rauch ist eine Metapher”, sagt er, während der Rauchmelder zustimmt.","level":"Level: Zen in Flammen"},{"name":"Der Ninja","motto":"„Hast du je einen Ninja abtrocknen sehen? Genau.”","desc":"Taucht genau auf, wenn das Fleisch fertig ist. Verschwindet genau, wenn das Geschirr gewaschen werden muss. Niemand hat ihn je Holzkohle tragen sehen. Urban Legends sagen, er existiert — bestätigen kann es niemand.","level":"Level: unsichtbar, aber satt"},{"name":"Der Planer","motto":"„Ich habe eine Tabelle gemacht. Ihr habt 5 Minuten zum Lesen.”","desc":"Besitzt eine Tabelle mit Mici pro Person, 48-Stunden-Wettervorhersage, Garzeiten-Diagramm und Evakuierungsplan. Sein Grill startet auf die Sekunde. Präzise. Erschreckend.","level":"Level: Hinterhof-NASA"},{"name":"Der Experimentierer","motto":"„Aber was wäre, wenn wir... Ananas nehmen?”","desc":"Legt Ananas auf den Grill. ANANAS. Auf. Den. Grill. Dann probiert er Mici mit Schokolade „für die Wissenschaft”. Die Community beobachtet ihn genau. Der Küchen-Roboter hat eine offizielle Beschwerde eingereicht.","level":"Level: verbotenes Labor"},{"name":"Der Veteran","motto":"„Ich grille seit '87. Ich akzeptiere keine Kritik.”","desc":"Sein Fleisch ist immer „perfekt”, selbst wenn es molekular verkohlt ist. Hat starke Meinungen über Holzkohle, Holz, Feuer und das Leben im Allgemeinen. Nicht diskutieren. Nicht mal versuchen.","level":"Level: General im Ruhestand"}]},"miciometru":{"title":"Mici-O-Meter 3000","subtitle":"Ein medizinisches Hochpräzisionsgerät, das misst, wie viele Mici du essen kannst. Genauigkeit: ±0 Mici. Einfach drücken und schauen, wie weit du kommst!","counterLabel":"Verzehrte Mici","unit":"Mici mit Ehre verschlungen","eat":"Iss ein Mici!","reset":"Zurücksetzen (der Arzt hat angerufen)","rangs":["Anfänger","Grill-Major","Legende"],"legendTarget":"Legende","milestones":["Fang an, Mutiger! Mindestens ein Mici. Der Roboter wartet gespannt. 🤖","Faulpelz! Sogar der Roboter isst mehr. Und der hat nicht mal einen Magen! 🤖","ES HAT BEGONNEN! Die Omas ändern langsam ihre Meinung über dich.","Respektabel! Du sprichst schon mit transsilvanischem Akzent. Keine Ahnung wie, aber es klingt nett.","GROSSARTIG! Oma weint vor Stolz. Oder vom Rauch. Schwer zu sagen.","DU HAST DEN RANG GRILL-MAJOR ERREICHT! Nur noch 30 Ränge bis zur Legende.","Wow. Einfach wow. Jemand bringt schon das zweite Senfglas. Es wird ernst.","LEGENDE IM AUFBAU! Die Nachbarn sammeln sich. Jemand hat Porzellan von der Arbeit mitgebracht.","BESTÄTIGTE LEGENDE! Du musst aus Siebenbürgen sein oder aus einer Familie von Champions.","DU HAST DIE MENSCHLICHEN GRENZEN ÜBERSCHRITTEN! Wir rufen den Roboter, dich aufzuhalten. Und der isst viel, es wird also ernst. 🤖🚨"],"disclaimer":"* Das Mici-O-Meter übernimmt keine Haftung für Völlegefühl, Mittagsschläfchen oder Träume von fliehenden Grills."},"quiz":{"title":"Quiz: Was für ein Griller bist du?","subtitle":"Vier Fragen. Ein Schicksal. Null falsche Antworten (nur leckere).","qOf":"Frage","of":"von","restart":"Quiz wiederholen, vielleicht läuft's besser 🔁","ghost":"(0-mal geantwortet? Geister-Griller? Beeindruckend.) 👻","resultTitle":"Dein Ergebnis ist...","questions":[{"q":"Was tust du, wenn jemand behauptet, jemand anders grille besser?","a":["„Interessante Theorie. Hast du das Thema studiert? Ich habe ein 40-seitiges Dokument vorbereitet.”","„Jeder hat seinen eigenen Weg zur Erleuchtung. Lasst uns nicht urteilen.”","„Du lächelst höflich, aber in deiner Seele hast du dich bereits zum Duell angemeldet.”"]},{"q":"Wann ist der perfekte Moment, den Grill anzuzünden?","a":["„14:00 Uhr scharf. Notiert. Nachgerechnet. Ich habe einen Backup-Plan.”","„Wenn mein Herz schreit: SEHR MÜDE, ABER AUCH HUNGRIG.”","„Wenn das Licht in 45 Grad fällt und der Himmel Picasso-Blau ist.”"]},{"q":"Was ist das Geheimnis eines perfekten Mici?","a":["„Geduld, Liebe und ein bisschen Rauch in den Augen.”","„Ihn nicht verbrennen. Der Rest sind Details, von denen ich nie gehört habe.”","„Das geheime Familienrezept. Von 1987. Nicht mal unter Folter.”"]},{"q":"Ein Gast bringt Ananas zum Grill. Deine Reaktion?","a":["„Interessant. Ich stelle ihn neben das Fleisch — nur für die Wissenschaft.”","„Ich fotografiere die Ananas aus 9 Winkeln, bevor jemand atmet.”","„Ich erscheine aus dem Schatten und konfisziere sie, diskret. Niemand sieht mich je.”"]}],"results":{"Philosopher":{"name":"Philosophen-Griller","desc":"Du und der Grill seid eine Seele. Du redest über den Sinn des Lebens, während das Fleisch sich selbst kocht (meist in Flammen). Du bist weise, ruhig und der Einzige, der sich erinnert, warum das Feuer entzündet wurde."},"Artist":{"name":"Künstler-Griller","desc":"Für dich ist der Grill eine Galerie, der Teller ein Rahmen und der Senf ein Pinsel. Jedes Mici wird fotografiert, gefiltert und präsentiert. Das Fleisch ist kalt geworden? Kein Problem. Der Content ist alles."},"Ninja":{"name":"Ninja-Griller","desc":"Niemand weiß, wo du herkommst, niemand weiß, wohin du gehst. Du erscheinst am Grill genau, wenn das Fleisch fertig ist, und verschwindest, wenn Geschirr gewaschen werden muss. Du bist eine gut gefütterte urbane Legende."},"Planner":{"name":"Planer-Griller","desc":"Dein Grill ist eine Militäroperation. Du hast eine Tabelle mit Mici pro Person, Wettervorhersagen und Plänen B, C und D. Nichts geht je schief. Nichts. Nie. (Bisher.)"},"Experimenter":{"name":"Experimentier-Griller","desc":"Für dich ist der Grill ein Labor. Mici mit Schokolade? Ja. Ananas auf dem Grill? JA. Die Community beobachtet dich, gibt aber zu: Manchmal, manchmal, hast du recht. Sehr selten. Sehr."},"Veteran":{"name":"Veteranen-Griller","desc":"Du grillst seit Generationen. Dein Fleisch ist immer „perfekt”, dein Feuer immer „richtig” und deine Meinungen über Holzkohle sind Gesetze. Mit dem Veteranen diskutiert man nicht. Man versucht es nicht mal."}}},"scuze":{"title":"Der Grill-Ausreden-Generator","subtitle":"Freunde laden dich zur Hochzeit ein? Zum Theater? Zu einem „gesunden Spaziergang”? Keine Sorge — wir haben Weltklasse-Ausreden, getestet an Schwiegermüttern.","placeholder":"Drück den Button und erhalte eine solide Ausrede, legal vom Küchen-Roboter verifiziert. 🤖","generate":"Ausrede generieren!","counter":"Bisher generierte Ausreden","legend":" — du rutschst von den Gästelisten, aber du bist die Legende des Grills! 🏆","items":["„Ich kann heute nicht kommen. Die Mici brauchen Aufmerksamkeit. Es ist eine Beziehungsfrage.”","„Der Arzt hat mir Grills verboten... die von anderen. Meiner ist medizinisch verordnet.”","„Ich habe einen wichtigen Termin: der Grill und ich. 14:00 Uhr. Im Hof. Nicht verschiebbar.”","„Jemand muss das Fleisch vor den Neugierigen bewachen. Ich habe mich gemeldet. Ich bin quasi ein Held.”","„Das Auto springt nicht an. Und es will auch nicht. Es riecht den Grillrauch und weigert sich zu fahren.”","„Ich bin allergisch gegen Tage ohne BBQ. Es ist ernst. Die Ärzte sind verwirrt.”","„Ich kann heute nicht fliegen, aber grillen. Fast das Gleiche, nur leckerer.”","„Der Chef hat mir frei gegeben für 'wichtige Geschäfte'. Die Mici SIND das Geschäft.”","„Ich habe meiner Schwiegermutter versprochen zu kommen... zum Grill. Wo ich sitze, hab ich nie gesagt. Juristisches Schlupfloch.”","„Heute nicht. Aber wer testet die Fleischqualität? Ich. Genau. Wir sind ein Team.”","„Heute nicht. Das Fleisch braucht mich emotional. Und ich es. Es ist gegenseitig.”","„Ich habe mir den Knöchel verstaucht. Beim Versuch, dem Grill Turnschuhe anzuziehen. Lange Geschichte.”","„Ich muss zuhause bleiben. Mein WLAN wartet. Und der Grill oben. Und der Kühlschrank.”","„Ich trainiere für den Mici-Marathon. Training unterbrechen? Undenkbar. Ich bin bei Mici 4 von 40.”","„Allergisch gegen Rauch, Ruß und Tage ohne BBQ. Die Ärzte sind ratlos. Ich habe mich damit arrangiert.”"]},"dictionar":{"title":"Das Wörterbuch des Grillers","subtitle":"Offizielle Begriffe, legale Definitionen (nicht wirklich), genehmigt von der Akademie des Hinterhof-Räucherns.","items":[{"term":"Mici (Substantiv)","phonetic":"/mitschi/","def":"Die grundlegende Glückseinheit. 1 Mici = 7 standardisierte Freuden-Einheiten. Obligatorisch mit Senf und Geschichten serviert. Plural: Mici (Glück multipliziert)."},{"term":"Senf (Substantiv)","phonetic":"/senf/","def":"Die heilige Flüssigkeit des Grillers. Kein Gewürz — ein Sakrament. Großzügig und mit Glauben gegossen. Wer Ketchup benutzt, wird freundlich gebeten zu gehen. (Halb Scherz.)"},{"term":"Rauch (Substantiv)","phonetic":"/rauch/","def":"Das offizielle Parfüm der Sommertage und die Hauptursache für nachbarliches Sabbern. Monate später auf Kleidung entdeckt — als treue Erinnerung an einen perfekten Tag."},{"term":"Gelegenheitsfresser (Substantiv)","phonetic":"/ge-le-gen-heits-fres-ser/","def":"Jemand, der genau dann am Grill auftaucht, wenn das Essen fertig ist, ohne etwas mitgebracht zu haben. Erkennung: isst mit Lichtgeschwindigkeit, verschwindet beim Spülen."},{"term":"geröstete Paprika (Substantiv)","phonetic":"/pa-pri-ka/","def":"Der beste Freund des Mici. Röstet langsam, mit Würde, und verlässt sofort jeden, der ihn ohne Brot isst. Es ist eine komplexe, aber schöne Beziehung."},{"term":"„ist er fertig?” (Ausdruck)","phonetic":"/ist er fer-tig/","def":"Verbotene Frage Nr. 1 am Grill. Vierzigmal wiederholt beschleunigt sie das Fleisch nicht — sie stresst nur den Griller. Alternative: „dauert es noch lange?” (verboten Nr. 2)."},{"term":"Grill-Veteran (Substantiv)","phonetic":"/ve-te-ran/","def":"Einer, der seit 1987 grillt und keine Kritik akzeptiert. Sein Fleisch ist immer „perfekt”, selbst jenseits des Kohlenstoff-Zustands. Respekt wird durch Rauch durchgesetzt."},{"term":"kaltes Bier (Substantiv)","phonetic":"/bier/","def":"Der Stern am Grillhimmel. Wer kaltes Bier bringt, sei gesegnet in Ewigkeit. Wer warmes Bier bringt, halte es in den Händen, mit Würde, bis es kühl wird."}]},"footer":{"brand":"🍖 NOXIS BBQ 🍖","copyright":"© 2026 NOXIS-Universum — Alle Mici werden respektiert. Kein Fleisch wurde beim Bau dieser Website absichtlich verbrannt. (Nur ein bisschen. Zweimal.)","comedyNote":"Comedy-Website. Definitionen, Ausreden und Ränge sind fiktiv. Die Mici hingegen sind sehr real. Grille verantwortungsvoll!","musicCredit":"🎵 TARA NOXIS — WHERE'S THE MUSTARD?! · Musik © Tara Noxis"}},
  "pl": {"meta":{"title":"NOXIS BBQ — BŁĄD 404: NIE ZNALEZIONO MUSZTARDY! 🌭🔥","description":"Musztarda zniknęła, robot gotuje, a Nyxer traci zmysły! Polowanie na musztardę, zamówienie 100 mici, Nyra inspektorka, Z230 przegrzana ślimaczysko i Ściana Komedii."},"nav":{"brand":"NOXIS BBQ","personaje":"Ekipa NOXIS","mustard":"Polowanie na musztardę","order":"100 Mici","stress":"Stres Nyxera","nyra":"Nakarm Nyrę","z230":"Z230","comandamente":"Przykazania","tipuri":"Typy grillomana","miciometru":"Mici-O-Metr","quiz":"Quiz","scuze":"Wymówki","dictionar":"Słownik","wall":"Ściana Komedii","langLabel":"Język","soundOn":"Dźwięk włączony","soundOff":"Dźwięk wyłączony","menu":"Sekcje"},"hero":{"badge":"🔥 Jedyna strona, która pachnie grillem 🔥","titleA":"NOXIS","titleB":"BBQ","tagline":"Tam gdzie brakuje musztardy, robot gotuje, a Nyxer traci zmysły!","subtitle":"Interaktywna komedia sci-fi: poluj na znikniętą musztardę, zamów 100 mici (BŁĄD 402!), nakarm kocą inspektorkę i nie daj staremu Z230 się roztopić. I tak, są też prawdziwe grillowane mici.","cta1":"Rozpocznij polowanie 🏺","cta2":"Zamów 100 Mici 🌭","footnote":"* Robot ze zdjęcia zjadł 47 mici podczas sesji zdjęciowej. Nikt go nie powstrzymał.","caption":"🤖 Robot Kucharz — gwiazda wizualna grilla NOXIS"},"seal":{"alt":"Pieczęć rodziny NOXIS","toast":"Pieczęć NOXIS mruczy z aprobatą. Rodzina patrzy na grill."},"generic":{"say":"Powiedz coś!","reset":"Resetuj","close":"Zamknij","attempts":"Próby"},"characters":{"title":"Ekipa NOXIS","subtitle":"Jedna rodzina, jeden grill, zero musztardy. Kliknij postać i usłysz, co o tym myśli.","familyCta":"Zobacz zdjęcie rodziny NOXIS!","familyTitle":"Rodzina NOXIS","familySubtitle":"Jedna rodzina. Jeden grill. Nieskończony chaos.","familyAlt":"Oficjalne zdjęcie rodziny NOXIS — Tara, Nyxer, Nyxar, Nyxin, AR_ON, AR_IN i Aren","familyCaption":"Oficjalny portret rodzinny. Brakuje musztardy, ale miłość (i chaos) są w komplecie.","roles":{"tara":{"name":"TARA NOXIS","role":"Twórczyni uniwersum NOXIS","desc":"Pomysłowa, zawsze pełna nowych idei. Zaczyna projekty, zanim Nyxer skończy liczyć koszty poprzedniego."},"nyxer":{"name":"NYXER NOXIS","role":"Dyrektor finansowy (panikujący)","desc":"Przerażony wydatkami, fakturami i projektami bez przychodów. Dramatycznie reaguje na każde zamówienie — nawet na burgera."},"aren":{"name":"AREN NOXIS","role":"Badacz i odkrywca GitHuba","desc":"Na każdy problem znajduje kolejne narzędzie open-source. Liczba repo rośnie szybciej niż temperatura grilla."},"nyra":{"name":"NYRA","role":"Najwyższa inspektorka restauracji","desc":"Niezależna, ironiczna, wymagająca. Uważa się za najwyższy autorytet kulinarny w uniwersum NOXIS. Łapki wliczone."},"z230":{"name":"Z230","role":"Stary komputer rodziny (jako ślimak)","desc":"Powolny, lojalny, ciepły. Żyje w strachu przed przegrzaniem i przed każdym, kto chce instalować mu nowe programy."},"robot":{"name":"ROBOT KUCHARZ","role":"Srebrny mistrz grilla","desc":"Sympatyczny srebrny robot ze świecącymi niebieskimi oczami. Grilluje mici do perfekcji i stale wywołuje absurdalne sytuacje."},"aron":{"name":"AR_ON NOXIS","role":"Prawa i licencje","desc":"Pojawia się znienacka, gdy ktoś używa obrazu bez pozwolenia. Mówi mało. Jego umowy przybywają przed nim."},"nyxar":{"name":"NYXAR NOXIS","role":"Administrator systemu","desc":"Utrzymuje cały wszechświat NOXIS online. Serwery, firewall, uptime — jego królestwo. Spokojny jak admin, który już zrobił backup. Wszystkiego. Dwa razy."},"arin":{"name":"AR_IN NOXIS","role":"Strażniczka historii","desc":"Mów. Zapisuj. Pamiętaj. Dokumentuje każdą grillową katastrofę dla przyszłych pokoleń — eleganckim lodowym błękitem."},"nyxin":{"name":"NYXIN NOXIS","role":"Kreacja wizualna","desc":"Rysuj. Projektuj. Pamiętaj. Każdy piksel uniwersum NOXIS rodzi się w jej dłoniach — czasem nawet podczas drzemki. Po prostu wygląda perfekcyjnie."}},"dialogues":{"tara":["Czekaj, mam pomysł na JESZCZE JEDEN projekt!","Zniknięcie musztardy? Inspirujące. Bardzo inspirujące.","Zamówiłam 100 mici. Finansowo? Nyxer wyjaśni."],"nyxer":["KTÓ WYDAŁ PIENIĄDZE?! KTÓ?! POKAŻCIE PARAGON!","13 projektów! ZERO przychodów! I teraz jeszcze nie ma musztardy!","Nie panikuję. Ja... agresywnie budżetuję."],"aren":["Znalazłem na GitHubie open-source'owy detektor musztardy!","Jest na to repo. ZAWSZE jest na to repo.","Zainstalowałem 14 nowych narzędzi. Rozwiązanie jest w jednym z nich. Chyba."],"nyra":["Miau. Wiem, gdzie jest musztarda. Ale informacja kosztuje.","Twoja technika grillowania? Dwie łapki w dół.","Skontrolowałam kuchnię. Zaliczona. Ledwo. Za sprawą mnie."],"z230":["Jak jeszcze coś mi zainstalujecie, zamienię się w ślimaka z grilla!","Ładowanie... powoli... jak zawsze... dajcie... minutę...","Moje wentylatory śpiewają. To nie jest dobry znak."],"robot":["Przygotowałem 100 mici. Musztardy nie ma w inwentarzu!","Poziom grilla: perfekcja. Poziom musztardy: BŁĄD 404.","Nie jem. Tylko gotuję. To tragedia dla wszystkich innych."],"aron":["Ogień mówił do mnie. Powiedział: więcej węgla.","Ja nie poluję na musztardę. Musztarda poluje na mnie.","Ciemność, cisza... i zapach mici. Idealnie."],"nyxar":["Próbowaliście wyłączyć i włączyć grill ponownie?","Ja nie mam problemów. Mam zgłoszenia. I wszystkie są zamknięte.","Musztardy nie ma w bazie danych. Sprawdziłem. Dwa razy. Z JOIN-ami."],"arin":["Dzień 1 kryzysu musztardowego. Zapisuję wszystko.","Każda legenda potrzebuje kronikarza. A każdy grill — świadka.","Mów. Zapisuj. Pamiętaj. Zwłaszcza tę część, gdzie zniknął słoik."],"nyxin":["Śniłam, że strona działa. Obudziłam się — i faktycznie działa.","Naprawiłam buga we śnie. Nie ma za co.","Nie jesteś zagubiony, tworzysz. A tak w ogóle, musztarda jest w lodówce."]}},"mustard":{"title":"Wielkie Polowanie na Musztardę","subtitle":"Mici gotowe. Musztarda zniknęła. Przeszukaj kuchnię NOXIS i znajdź słoik — śledź wskazówki!","errorTitle":"BŁĄD 404 — NIE ZNALEZIONO MUSZTARDY!","robotAnnounce":"Robot Kucharz ogłasza: mici są gotowe... ale musztardy NIE MA w inwentarzu!","start":"Rozpocznij poszukiwania!","searchHint":"Kliknij (lub naciśnij Enter) na obiekt, aby go przeszukać.","attemptsLabel":"Przeszukania","spots":["Lodówka","Szafka górna","Szafka dolna","Piekarnik","Mikrofalówka","Półka na przyprawy","Słoik z ciastkami","Pod zlewem","Spiżarnia","Kosz na śmieci","Skrzynka z narzędziami","Pudełko z dekoracjami świątecznymi"],"cluesNear":["Robi się tu ciepło... musztarda jest BLISKO!","Nyra czuje musztardę w pobliżu. Ale nic nie mówi.","Szuflada z łyżkami drży. Musi być blisko!"],"cluesFar":["Nic tu nie ma. Musztarda jest DALEKO od tego miejsca.","Z230 przeskanował okolicę: prawdopodobieństwo musztardy 3%. Szukaj gdzie indziej.","Zimno. Zimniej niż reakcja Nyxera na faktury w tym miesiącu."],"decoys":[{"title":"Butelka ketchupu!","text":"To ketchup. KETCHUP. Nyra obraziła się, że w ogóle jej dotknąłeś."},{"title":"Zgubiona skarpetka...","text":"Czemu w kuchni leży skarpetka? Rodzina NOXIS ma pytania. Bez odpowiedzi."},{"title":"Ulubiona zabawka Nyry!","text":"Mała pluszowa myszka. Odłożyłeś ją bardzo, bardzo ostrożnie."}],"reactions":{"robot":["Musztardy nadal brak. Przeliczam przepisy bez niej. Poziom smutku rośnie.","Sprawdziłem inwentarz dwa razy. Słoik odmawia istnienia."],"nyxer":["KTÓ KUPIŁ 100 MICI BEZ MUSZTARDY?!","Wiesz, ile teraz kosztuje musztarda?! Nieważne — I TAK JEJ NIE MAMY!"],"aren":["Znalazłem na GitHubie open-source'owy detektor musztardy! Ma 14 zależności.","Nowe repo odkryte: 'mustard-tracker-9000'. Ostatni commit: 3 lata temu. Idealnie."],"nyra":["Miau. Wiem dokładnie, gdzie jest. Ale informacja kosztuje.","Amatorzy. Ja znalazłabym go w 3 sekundy. Z zamkniętymi oczami. Z zasady."],"z230":["Jak zainstalujecie mi jeszcze jedną aplikację do skanowania musztardy, zamienię się w ślimaka z grilla!","Skanuję... powoli... kuchnię... proszę... czekać..."],"tara":["Szukajcie lepiej! W międzyczasie mam pomysł na inny projekt!","Kryzys musztardowy mnie zainspirował. Projektuję park rozrywki w stylu musztardy."],"aron":["Czuję... słoik. Albo cień. Raczej cień.","Ciemność ukrywa wiele rzeczy. W tym musztardę. Niestety."],"nyxar":["Wdrożyłem usługę wyszukiwania musztardy. Uptime: 100%. Znalezione słoiki: 0.","Logi serwera mówią, że Nyra ją wzięła. Nie oceniam. Tylko loguję."]},"win":{"title":"MUSZTARDA ZNALEZIONA! ...czy na pewno?","found":"Znalazłeś słoik! Ukryty przez absolutnie nikogo, widoczny dla wszystkich.","empty":"Otwierasz go powoli... JEST PUSTY.","robotConfession":"Robot Kucharz się przyznaje: „Użyłem ostatniej kropli musztardy do 100 mici. Moje obwody logiczne niczego nie żałują.”","nyraLine":"Nyra: „Miau. Ja to wiedziałam od początku. Informacja kosztuje, pamiętasz?”","again":"Poluj ponownie (może tym razem będzie musztarda)"}},"order402":{"title":"Zamów 100 Mici","subtitle":"Jeden przycisk. Jedno zamówienie. Jeden kompletny załamanie nerwowe CFO.","button":"ZAMÓW 100 MICI!","errorTitle":"BŁĄD 402 — WYMAGANA PŁATNOŚĆ!","errorSub":"System finansowy NOXIS został powiadomiony. A przez „powiadomiony” rozumiemy „podpalony”.","panic":["Nyxer: „STO mici?! Kto to zatwierdził?! KTÓ MA BUDŻET?!\"","Nyxer: „Węgiel, mięso, przyprawy, serwetki... się mnożą... liczby SIĘ MNOŻĄ!”","Nyxer: „Jesteśmy stroną komediową, nie firmą cateringową!”"],"taraLine":"Tara: „Nyxer, oddychaj. To symulacja. Nikt niczego nie kupuje.”","nyxerFinal":"Nyxer: „NIE MA NIC NAWET MICI NIE SĄ PRAWDZIWE?!\"","disclaimer":"Czysta komedia: żadnych prawdziwych płatności, żadnych danych bankowych, żadnych faktycznie zamówionych mici. Twój portfel jest bezpieczny. Nyxerowego nie.","again":"Zamów ponownie (Nyxer to uwielbia)"},"stress":{"title":"Poziom stresu Nyxera","subtitle":"Na żywo: miernik nerwów dyrektora finansowego NOXIS. Każde zdarzenie na stronie go zasila. Konsumuj odpowiedzialnie.","reasons":{"order":"Ktoś zamówił 100 mici za darmo.","mustard":"Polowanie na musztardę się skończyło. Słoik był pusty.","wrongSearch":"Kolejne nieudane przeszukanie kuchni.","chaosTara":"Tara rozpoczęła zupełnie nowy projekt.","chaosAren":"Aren odkrył na GitHubie jeszcze jedną umiejętność.","chaosRobot":"Robot zamówił więcej składników.","chaosNyra":"Nyra zażądała specjalnego menu.","chaosZ230":"Z230 zagroził wyłączeniem.","nyraMenu":"Specjalne menu Nyry zostało zatwierdzone.","z230hot":"Z230 jest niebezpiecznie blisko roztopienia."},"levels":{"calm":"Nyxer jest spokojny. Podejrzanie spokojny.","worried":"Nyxer sprawdza faktury. Znowu.","panicked":"Nyxer biega między arkuszami kalkulacyjnymi.","meltdown":"CAŁKOWITE ZAŁAMANIE. Zakryj kalkulatory!"},"shout":"13 PROJEKTÓW! ZERO PRZYCHODÓW! I TERAZ NIE MAMY NAWET MUSZTARDY!","chaos":"Wywołaj losowy chaos","reset":"Postaw Nyxerowi piwo 🍺","logTitle":"Najnowsze incydenty:","emptyLog":"Jeszcze nic się nie stało. Nyxer nie ufa.","afterReset":"Nyxer: „Jestem teraz spokojny. Całkowicie spokojny. Nie dotykajcie niczego.”"},"nyra":{"title":"Nakarm Nyrę","subtitle":"Zaoferuj dania najwyższej inspektorce. Niektóre akceptuje, większość odrzuca, zawsze ocenia.","foods":{"salmon":"Grillowany łosoś","chicken":"Prosty kurczak","egg":"Jajko na twardo","cheese":"Kostka sera","shrimp":"Krewetka","milk":"Mleko krowie","onion":"Cebula","garlic":"Czosnek","chocolate":"Czekolada","grapes":"Winogrona"},"offer":"Zaoferuj","accepted":["Miau. Akceptowalne. Dla człowieka.","Nyra skosztowała. Powoli. „Miałam lepsze. Dodaj do mojej teczki.”","„Nadaje się do jedzenia. Obsługa nadal fatalna.”"],"disdain":["Nyra patrzy na danie. Potem na ciebie. Potem z powrotem na danie. „Nie.”","„Miau. Ja kontroluję restauracje. Nie jem ich błędów.”","Powąchała raz i odeszła z królewskim rozczarowaniem."],"reject":["„{food}?! Próbujesz otruć inspektorkę?! To TOKSYCZNE dla kotów!”","„Absolutnie nie. {food} jest niebezpieczne dla kotów. Jedna gwiazdka. Gdybym mogła dać zero, dałabym.”","„{food} — odrzucone. Moje wąsy wykrywają niebezpieczeństwo. I zły gust.”"],"specialMenu":"Nyra skomponowała swoje specjalne menu.","nyxerQuestion":"Nyxer: „Stój... ile KOSZTUJE specjalne menu?”","nyraAnswer":"Nyra: „Miau. Dopisz to na TWOJE konto!”","vetNote":"Gra komediowa — w prawdziwym życiu nigdy nie karm kotów jedzeniem z grilla. Cebula, czosnek, czekolada i winogrona są toksyczne dla kotów. W razie wątpliwości: pytaj weterynarza.","unsafeLabel":"Niebezpieczne dla kotów","safeLabel":"Bezpieczne dla kotów (w grze)"},"z230":{"title":"Z230 — Przegrzana ślimaczysko","subtitle":"Stary komputer rodziny patrzy na grill z grozą. Uruchom BBQ i zobacz, jak długo przetrwa.","start":"URUCHOM GRILLA!","stop":"Chłodzenie (ratuj ślimaka)","react":"Z230: „NIE NA MOIM PROCESORZE!”","lines":{"warm":["Z230: „Robi się tu ciepło, czy to tylko moje wrażenie?”","Z230: „Otwieram wszystkie moje wentylatory. Wszystkie. Czyli dwa.”"],"hot":["Z230: „Jestem oficjalnie fondue ze ślimaka. To nie jest metafora.”","Z230: „Jeśli teraz zamarznię, powiedzcie moim plikom, że je kochałem.”"],"critical":["Z230: „AWARIA! Jestem o jeden stopień od stania się ślimakiem z grilla!”","Z230: „Wyłączam się za 3... 2... chyba że ktoś mnie TERAZ schłodzi!”"]},"tempLabel":"Temperatura komediowa","disclaimer":"Jednostki są w 100% komediowe (°SN — Jednostki Ślimacze). Ten termometr nie mierzy niczego prawdziwego.","shutdown":"Z230 dramatycznie zemdlewał. Będzie dobrze. Zawsze jest."},"wall":{"title":"NOXIS BBQ — Ściana Komedii","subtitle":"Zostaw żart, komentarz, grillowe wyznanie. W dowolnym języku. Nyra i tak to oceni.","nickname":"Pseudonim","nicknamePh":"np. FanMusztardy42","comment":"Komentarz","commentPh":"Twoja najzabawniejsza historia z grilla...","post":"Opublikuj komentarz","reply":"Odpowiedz","replyPh":"Twoja odpowiedź...","cancelReply":"Anuluj","like":"Lubię","deleted":"Komentarz usunięty przez moderatora. Nyra zatwierdziła.","adminMode":"Tryb moderatora","adminPassword":"Hasło moderatora","adminLogin":"Zaloguj się","adminLogout":"Wyloguj się","delete":"Usuń","wrongPassword":"Złe hasło. Nyra na ciebie patrzy.","moderatorOn":"Tryb moderatora WŁĄCZONY.","moderatorOff":"Tryb moderatora wyłączony.","empty":"Ściana jest pusta. Bądź pierwszą legendą!","loading":"Ładowanie komedii...","postedOk":"Komentarz opublikowany! Rodzina NOXIS cię pozdrawia.","spamFast":"Powoli, legendą! Za dużo komentarzy za szybko. Spróbuj za minutę.","spamBlocked":"Ślimak antyspamowy NOXIS to zablokował. Spróbuj czegoś innego.","badContent":"Nyra odrzuciła twój komentarz. Bądź przyjazny i zabawny!","nicknameBad":"Pseudonim potrzebuje 2-24 znaków. Jak każda legenda.","commentBad":"Komentarz potrzebuje 2-500 znaków.","demoNotice":"Bez konta, bez rejestracji: piszesz, publikujesz, śmiejesz się. Twój pseudonim i komentarz są widoczne dla wszystkich odwiedzających; adres IP służy wyłącznie ochronie przed spamem i nigdy nie jest wyświetlany.","translate":"Przetłumacz","translating":"Tłumaczenie...","translateNote":"Tłumaczenie AI (prawdziwa usługa, może być niedoskonała).","translateError":"Usługa tłumaczeń jest chwilowo niedostępna. (Nyra pewnie wyciągnęła wtyczkę.) Komentarz zostaje w oryginalnym języku — tutaj nie ma wymyślonych tłumaczeń.","translateFast":"Maszyna do tłumaczeń się chłodzi. Spróbuj ponownie za kilka sekund.","offlineTitle":"Publiczne komentarze wymagają serwera","offlineBody":"Ta wersja NOXIS BBQ działa bezpośrednio w NOXIS UNIVERS, bez serwera. Publiczne komentarze, odpowiedzi, lajki, tłumaczenie AI i moderacja działają tylko w pełnej wersji Next.js z backendem (zobacz INTEGRARE.md). Nic tu nie jest symulowane — Nyra nie toleruje fałszywek.","offlineHint":"📍 Notatka lokalna dla UNIVERS — to NIE jest sekcja publicznych komentarzy.","backendDoc":"Plik BACKEND-NECESAR.md w archiwum opisuje wszystko, co potrzebne; pełna wersja Next.js (noxis-bbq-complete.zip) ma już gotowy backend.","rules":"Bądź zabawny, bądź uprzejmy. Bez danych osobowych. Ślimak moderuje."},"music":{"welcomeTitle":"WITAJ W NOXIS BBQ!","welcomeSub":"100 mici. Jedna zaginiona musztarda. Nieskończony chaos!","enterMusic":"🎸 WEJDŹ DO NOXIS BBQ — PODKRĘĆ MUZYKĘ!","enterSilent":"🔇 WEJDŹ BEZ MUZYKI","play":"Odtwórz","pause":"Pauza","mute":"Wycisz","unmute":"Włącz dźwięk","volume":"Głośność","nowPlaying":"Teraz odtwarzane","credits":"TARA NOXIS — WHERE'S THE MUSTARD?! · Muzyka © Tara Noxis"},"comandamente":{"title":"10 Przykazań Grilla","subtitle":"Zapisane dymem na stalowej tablicy, znalezione obok babciowego grilla.","items":[{"title":"Nigdy nie grilluj głodny","text":"Zjesz surowe mięso z rozpaczy i przekonasz siebie, że „tak się to u nas robi”. Wytrzymaj, bohaterze. Najpierw chociaż kromka chleba."},{"title":"Czcij musztardę, bo cię wyniesie","text":"Musztarda to nie przyprawa. To religia. Kto je mici bez musztardy, ryzykuje wykluczenie z cechu grillowiczów i oceniające spojrzenia babć."},{"title":"Nie zapomnij soli!","text":"Bóg grilla nie wybacza mdłego mięsa. Mięso bez soli jest jak żart bez puentu: istnieje, ale nie daje radości."},{"title":"Pilnuj grilla na życie","text":"Psy sąsiadów czają się. Koty się śmieją. A wujek Gheorghe „tylko patrzy” od 2009. Stój blisko. Zawsze."},{"title":"Dym w oczach to chrzest prawdziwego grillomana","text":"Jak nigdy nie płakałeś przy grillu, to nie żyłeś. Łzy od dymu NIE liczą się jako emocje. Liczą się jako certyfikat."},{"title":"Nie licz zjedzonych mici","text":"Liczy tylko to, jak bardzo jesteś szczęśliwy. Liczba mici to temat kontrowersyjny i nie wolno o nim rozmawiać z partnerem ani z lekarzem."},{"title":"Mały ogień dla nowicjuszy, duży dla bohaterów","text":"Z umiarem, jednak. Nie chcemy wzywać strażaków przez trzeciego mici. W zeszłym roku był wypadek. W tym roku był „eksperyment”."},{"title":"Kto przynosi zimne piwo, niech będzie błogosławiony","text":"Na wieki wieków zimne piwo to gwiazda grillowego nieba. Kto przyniesie ciepłe, zostanie grzecznie poproszony, żeby trzymał je w rękach, aż wystygnie."},{"title":"Nie pytaj „czy już gotowe?”","text":"Grill sam wie, kiedy jest gotowy. Pytanie „czy już gotowe?” powtórzone 40 razy nie przyspiesza procesu — tylko stresuje mięso. Mięso też ma uczucia."},{"title":"Miłuj sąsiada, ale nigdy nie dawaj mu pierwszego mici","text":"Zasady to zasady. Pierwsze mici należy się grillomanowi. To trzecie prawo dynamiki grilla. My go nie wymyśliliśmy. Tylko się poddajemy."}]},"tipuri":{"title":"6 Typów Grillomanów","subtitle":"Spotkałeś ich wszystkich. Wszyscy istnieją. Jeden z nich to być może ty. (Jeśli jesteś Eksperymentatorem, proszę: nie.)","items":[{"name":"Artysta","motto":"„Każde mici to dzieło sztuki.”","desc":"Prezentuje mięso jak wystawę na biennale. Fotografuje każde mici 15 razy, z 9 kątów, zanim je zje. Potem mięso jest zimne. Nie obchodzi go to. Sztuka.","level":"Poziom: podwórkowe Louvre"},{"name":"Filozof","motto":"„Ale co NAPRAWDĘ jest mici?”","desc":"Spędza 3 godziny przy grillu, mówiąc o sensie życia, wszechświata i całej reszty. W międzyczasie mięso się pali. „Dym jest metaforą” — mówi, a czujnik dymu przytakuje.","level":"Poziom: Zen w płomieniach"},{"name":"Ninja","motto":"„Widziałeś kiedyś ninję zmywającego naczynia? Dokładnie.”","desc":"Pojawia się dokładnie, gdy mięso jest gotowe. Znika dokładnie, gdy trzeba zmywać. Nikt nigdy nie widział go z węglem. Legendy miejskie mówią, że istnieje — nikt nie może potwierdzić.","level":"Poziom: niewidzialny, ale najedzony"},{"name":"Planista","motto":"„Zrobiłem arkusz. Macie 5 minut na przeczytanie.”","desc":"Ma arkusz z liczbą mici na osobę, 48-godzinną prognozą pogody, wykresem czasów gotowania i planem ewakuacji. Jego grill startuje co do sekundy. Precyzyjnie. Przerażająco.","level":"Poziom: podwórkowa NASA"},{"name":"Eksperymentator","motto":"„A co gdyby dodać... ananasa?”","desc":"Kładzie ananasa na grill. ANANASA. Na. Grill. Potem próbuje mici z czekoladą „dla nauki”. Społeczność uważnie go obserwuje. Robot Kucharz złożył już oficjalną skargę.","level":"Poziom: zakazane laboratorium"},{"name":"Weteran","motto":"„Grilluję od '87. Nie przyjmuję krytyki.”","desc":"Jego mięso jest zawsze „idealne”, nawet kiedy jest skarbonizowane na poziomie molekularnym. Ma mocne zdanie o węglu, drewnie, ogniu i życiu w ogóle. Nie dyskutuje się. Nie nawet próbuj.","level":"Poziom: generał na emeryturze"}]},"miciometru":{"title":"Mici-O-Metr 3000","subtitle":"Medyczne urządzenie najnowszej generacji, które mierzy, ile mici możesz zjeść. Precyzja: ±0 mici. Po prostu naciskaj i patrz, jak daleko zajdziesz!","counterLabel":"Zjedzone mici","unit":"mici pożarte z honorem","eat":"Zjedz mici!","reset":"Reset (lekarz zadzwonił)","rangs":["Nowicjusz","Grill-Major","Legenda"],"legendTarget":"Legenda","milestones":["Zaczynaj, dzielny! Chociaż jedno mici. Robot patrzy z nadzieją. 🤖","Leniu! Nawet robot je więcej. A on nie ma nawet żołądka! 🤖","TO SIĘ ZACZĘŁO! Babcie powoli zmieniają o tobie zdanie.","Szanownie! Mówisz już z siedmiogrodzkim akcentem. Nie wiem jak, ale brzmi fajnie.","WIELKIE! Babcia płacze z dumy. Albo od dymu. Trudno powiedzieć.","OSIĄGNĄŁEŚ RANGĘ GRILL-MAJOR! Tylko 30 rang do Legendy.","Wow. Po prostu wow. Ktoś już przynosi drugi słoik musztardy. To poważne.","LEGENDA W BUDOWIE! Sąsiedzi zaczynają się zbierać. Ktoś przyniósł porcelanę z pracy.","POTWIERDZONA LEGENDA! Musisz być z Siedmiogrodu albo z rodziny czempionów.","PRZEKROCZYŁEŚ LUDZKIE GRANICE! Dzwonimy po robota, żeby cię zatrzymał. A on dużo je, więc poważnie. 🤖🚨"],"disclaimer":"* Mici-O-Metr nie odpowiada za niestrawność, drzemkę po obiedzie ani sny o uciekających grillach."},"quiz":{"title":"Quiz: Jaki jesteś grilloman?","subtitle":"Cztery pytania. Jeden los. Zero złych odpowiedzi (tylko pyszne).","qOf":"Pytanie","of":"z","restart":"Powtórz quiz, może pójdzie lepiej 🔁","ghost":"(Odpowiedziałeś 0 razy? Duch grillowania? Imponujące.) 👻","resultTitle":"Twój wynik to...","questions":[{"q":"Co robisz, gdy ktoś twierdzi, że ktoś inny lepiej grilluje?","a":["„Interesująca teoria. Badałeś temat? Przygotowałem dokument na 40 stron.”","„Każdy ma własną drogę do oświecenia. Nie osądzajmy.”","„Uśmiechasz się uprzejmie, ale w duszy już zapisałeś się na pojedynek.”"]},{"q":"Kiedy jest idealny moment na rozpalenie grilla?","a":["„14:00 ostro. Zanotowane. Przeliczone. Mam plan awaryjny.”","„Kiedy serce krzyczy: BARDZO ŚPIO, ALE TEŻ GŁODNY.”","„Kiedy światło pada pod 45 stopni, a niebo jest picassowsko niebieskie.”"]},{"q":"Jaka jest tajemnica idealnego mici?","a":["„Cierpliwość, miłość i trochę dymu w oczach.”","„Nie spalić go. Reszta to szczegóły, o których nigdy nie słyszałem.”","„Sekretny rodzinny przepis. Z 1987. Nie powiem nawet pod torturami.”"]},{"q":"Gość przynosi ananasa na grill. Twoja reakcja?","a":["„Ciekawe. Postawię go obok mięsa — ale tylko dla nauki.”","„Fotografuję ananasa z 9 kątów, zanim ktokolwiek odetchnie.”","„Pojawiam się z cienia i konfiskuję go, dyskretnie. Nikt mnie nigdy nie widzi.”"]}],"results":{"Philosopher":{"name":"Filozoficzny grilloman","desc":"Ty i grill jesteście jedną duszą. Rozmawiasz o sensie życia, podczas gdy mięso gotuje się samo (zwykle w płomieniach). Jesteś mądry, spokojny i jedyny pamiętasz, po co rozpalono ogień."},"Artist":{"name":"Artystyczny grilloman","desc":"Dla ciebie grill to galeria, talerz to rama, a musztarda to pędzel. Każde mici jest fotografowane, filtrowane i prezentowane. Mięso zastygło? Nie problem. Content to wszystko."},"Ninja":{"name":"Ninja grilloman","desc":"Nikt nie wie, skąd przychodzisz, nikt nie wie, dokąd idziesz. Pojawiasz się przy grillu dokładnie, gdy mięso gotowe, i znikasz, gdy trzeba zmywać. Jesteś dobrze nakarmioną miejską legendą."},"Planner":{"name":"Planistyczny grilloman","desc":"Twój grill to operacja wojskowa. Masz arkusz z liczbą mici na osobę, prognozy pogody i plany B, C oraz D. Nigdy nic nie idzie źle. Nigdy. Nic. (Jak dotąd.)"},"Experimenter":{"name":"Eksperymentalny grilloman","desc":"Dla ciebie grill to laboratorium. Mici z czekoladą? Tak. Ananas na grillu? TAK. Społeczność cię obserwuje, ale przyznaje: czasem, czasem masz rację. Bardzo rzadko. Bardzo."},"Veteran":{"name":"Weteran grillowania","desc":"Grillujesz pokoleniami. Twoje mięso jest zawsze „idealne”, ogień zawsze „prawidłowy”, a zdanie o węglu to prawa. Z weteranem się nie dyskutuje. Nie nawet próbuj."}}},"scuze":{"title":"Generator Wymówek Grillowych","subtitle":"Znajomi zapraszają na wesele? Do teatru? Na „zdrowy spacer”? Nie martw się — mamy wymówki klasy światowej, testowane na teściowych.","placeholder":"Naciśnij przycisk i otrzymaj solidną wymówkę, prawnie zweryfikowaną przez Robota Kucharza. 🤖","generate":"Generuj wymówkę!","counter":"Dotychczas wygenerowane wymówki","legend":" — spadasz z list gości, ale jesteś Legendą grilla! 🏆","items":["„Nie mogę dziś przyjść. Mici wymagają uwagi. To kwestia relacji.”","„Lekarz zakazał mi grillów... cudzych. Mój jest przepisany medycznie.”","„Mam ważne spotkanie: grill i ja. 14:00. Na podwórku. Nie do przełożenia.”","„Ktoś musi strzec mięsa przed ciekawskimi. Zgłosiłem się na ochotnika. Jestem w zasadzie bohaterem.”","„Samochód nie odpala. I nie chce. Czuje dym z grilla i odmawia jazdy.”","„Jestem uczulony na dni bez grilla. To poważne. Lekarze są zdezorientowani.”","„Nie mogę dziś latać, ale mogę grillować. Prawie to samo, tylko smaczniejsze.”","„Szef dał mi wolne na 'ważne sprawy'. Mici TO SĄ te sprawy.”","„Obiecałem teściowej, że przyjdę... do grilla. Gdzie usiądę — nie mówiłem. Luka prawna.”","„Dziś nie mogę. Ale kto sprawdzi jakość mięsa? Ja. Dokładnie. Jesteśmy zespołem.”","„Dziś nie mogę. Mięso mnie emocjonalnie potrzebuje. I ja je. To wzajemne.”","„Skręciłem kostkę. Próbując założyć grillowi adidasy. Długa historia.”","„Muszę zostać w domu. Czeka na mnie WiFi. I grill na górze. I lodówka.”","„Trenuję do Maratonu Mici. Nie mogę przerywać treningu. Jestem przy mici 4 z 40.”","„Alergia na dym, sadzę i dni bez grilla. Lekarze są bezradni. Ja się już pogodziłem.”"]},"dictionar":{"title":"Słownik Grillomana","subtitle":"Oficjalne terminy, legalne definicje (nie do końca), zatwierdzone przez Akademię Podwórkowego Wędzenia.","items":[{"term":"mici (rzeczownik)","phonetic":"/miczi/","def":"Podstawowa jednostka szczęścia. 1 mici = 7 znormalizowanych jednostek radości. Podawane obowiązkowo z musztardą i historiami. Liczba mnoga: mici (szczęście mnożone)."},{"term":"musztarda (rzeczownik)","phonetic":"/musz-tar-da/","def":"Święty płyn grillowicza. Nie przyprawa — sakrament. Nalewana hojnie i z wiarą. Kto używa ketchupu, proszony jest grzecznie o wyjście. (W połowie żartem.)"},{"term":"dym (rzeczownik)","phonetic":"/dym/","def":"Oficjalny perfum dni letnich i główna przyczyna ślinienia się sąsiadów. Wykrywany na ubraniach miesiące później — jako wierna pamiątka doskonałego dnia."},{"term":"okazjonizor (rzeczownik)","phonetic":"/ok-za-sjo-ni-zor/","def":"Osoba, która pojawia się przy grillu dokładnie, gdy jedzenie gotowe, a niczego nie przyniosła. Identyfikacja: je z prędkością światła, znika przy zmywaniu."},{"term":"pieczona papryka (rzeczownik)","phonetic":"/pa-pry-ka/","def":"Najlepszy przyjaciel mici. Piecze się powoli, z godnością, i natychmiast porzuca każdego, kto je ją bez chleba. To złożona, ale piękna relacja."},{"term":"„czy już gotowe?” (wyrażenie)","phonetic":"/czy dżu go-to-we/","def":"Zakazane pytanie nr 1 przy grillu. Powtórzone 40 razy nie przyspiesza mięsa — tylko stresuje grillowicza. Alternatywa: „jeszcze długo?” (zakazane nr 2)."},{"term":"weteran grilla (rzeczownik)","phonetic":"/we-te-ran/","def":"Ten, kto grilluje od 1987 i nie przyjmuje krytyki. Jego mięso jest zawsze „idealne”, nawet po stanie węglowym. Szacunek egzekwowany dymem."},{"term":"zimne piwo (rzeczownik)","phonetic":"/pi-wo/","def":"Gwiazda grillowego nieba. Kto przynosi zimne piwo, błogosławiony będzie na wieki. Kto przynosi ciepłe, ten trzyma je w rękach, z godnością, aż wystygnie."}]},"footer":{"brand":"🍖 NOXIS BBQ 🍖","copyright":"© 2026 Uniwersum NOXIS — Wszystkie mici są szanowane. Żadne mięso nie zostało celowo spalone podczas tworzenia tej strony. (Tylko trochę. Dwa razy.)","comedyNote":"Strona komediowa. Definicje, wymówki i rangi są fikcyjne. Mici natomiast są bardzo prawdziwe. Grilluj odpowiedzialnie!","musicCredit":"🎵 TARA NOXIS — WHERE'S THE MUSTARD?! · Muzyka © Tara Noxis"}},
  "sl": {"meta":{"title":"NOXIS BBQ — NAPAKA 404: GORČICA NI NAJDEN! 🌭🔥","description":"Gorčica manjka, robot kuha, Nyxer pa izgublja razum! Lov na gorčico, naročilo 100 mici, Nyra inšpektorka, Z230 pregret polž in Stena komedije."},"nav":{"brand":"NOXIS BBQ","personaje":"NOXIS ekipa","mustard":"Lov na gorčico","order":"100 Mici","stress":"Nyxerjev stres","nyra":"Nahrani Nyro","z230":"Z230","comandamente":"Zapovedi","tipuri":"Vrste žararjev","miciometru":"Mici-O-Meter","quiz":"Kviz","scuze":"Izgovorjave","dictionar":"Slovar","wall":"Stena komedije","langLabel":"Jezik","soundOn":"Zvok vklopljen","soundOff":"Zvok izklopljen","menu":"Razdelki"},"hero":{"badge":"🔥 Edina stran, ki diši po žaru 🔥","titleA":"NOXIS","titleB":"BBQ","tagline":"Kjer manjka gorčica, robot kuha, Nyxer pa izgublja razum!","subtitle":"Interaktivna znanstvenofantastična komedija: lovi izginjeno gorčico, naroči 100 mici (NAPAKA 402!), nahranite mačjo inšpektorko in rešite starega Z230 pred taljenjem. In ja — samo seveda so tu pravi mici z žara.","cta1":"Začni lov na gorčico 🏺","cta2":"Naroči 100 mici 🌭","footnote":"* Robot na fotografiji je jedel 47 mici med snemanjem. Nihče ga ni ustavil.","caption":"🤖 Robot kuhar — vizualna zvezda NOXIS žara"},"seal":{"alt":"Pečat družine NOXIS","toast":"Pečat NOXIS zadovoljno mrmra. Družina opazuje žar."},"generic":{"say":"Reci kaj!","reset":"Ponastavi","close":"Zapri","attempts":"Poskusi"},"characters":{"title":"Ekipa NOXIS","subtitle":"Ena družina, en žar, nič gorčice. Klikni lik in poslušaj, kaj si o vsem misli.","familyCta":"Poglej fotografijo družine NOXIS!","familyTitle":"Družina NOXIS","familySubtitle":"Ena družina. En žar. Neskončni kaos.","familyAlt":"Uradna družinska fotografija NOXIS — Tara, Nyxer, Nyxar, Nyxin, AR_ON, AR_IN in Aren","familyCaption":"Uradni družinski portret. Gorčice ni, a ljubezen (in kaos) sta v celoti prisotna.","roles":{"tara":{"name":"TARA NOXIS","role":"Ustvarjalka vesolja NOXIS","desc":"Izumiteljska, vedno polna novih idej. Začne projekte, še preden Nyxer konča izračune za prejšnjega."},"nyxer":{"name":"NYXER NOXIS","role":"Finančni direktor (prestrašen)","desc":"Prestrašen zaradi stroškov, računov in projektov brez prihodkov. Na vsako naročilo se odzove dramatično — celo na burger."},"aren":{"name":"AREN NOXIS","role":"Raziskovalec & raziskovalec GitHuba","desc":"Za vsak problem najde še eno odprtokodno orodje. Število repozitorijev raste hitreje kot temperatura žara."},"nyra":{"name":"NYRA","role":"Najvišja inšpektorka restavracije","desc":"Neodvisna, ironična, zahtevna. Velja za najvišjo kulinarično avtoriteto v vesolju NOXIS. Tačke vključene."},"z230":{"name":"Z230","role":"Stari družinski računalnik (kot polž)","desc":"Počasen, zvest, topel. Živi v strahu pred pregrevanjem — in pred vsakim, ki mu hoče namestiti nov program."},"robot":{"name":"ROBOT KUHAR","role":"Srebrni mojster žara","desc":"Prijazen srebrni robot s svetlečimi modrimi očmi. Mici pripravi popolnoma in nenehno povzroča absurdne situacije."},"aron":{"name":"AR_ON NOXIS","role":"Pravice in licence","desc":"Pojavi se iz nikjer, takoj ko nekdo uporabi sliko brez dovoljenja. Malo govori. Njegove pogodbe pridejo prej kot on."},"nyxar":{"name":"NYXAR NOXIS","role":"Sistemski skrbnik","desc":"Ohranja celotno vesolje NOXIS na spletu. Strežniki, požarni zid, uptime — njegovo kraljestvo. Miren kot skrbnik, ki je varnostno kopijo že naredil. Vsega. Dvakrat."},"arin":{"name":"AR_IN NOXIS","role":"Čuvalka zgodb","desc":"Povej. Zapiši. Zapomni si. Vsako žarsko katastrofo zabeleži za prihodnje rodove — v elegantni ledenomodri barvi."},"nyxin":{"name":"NYXIN NOXIS","role":"Vizualna kreacija","desc":"Riši. Oblikuj. Zapomni si. Vsak piksel vesolja NOXIS rodi se v njenih rokah — včasih celo med dremežem. Preprosto izgleda popolnoma."}},"dialogues":{"tara":["Počakaj, imam idejo za ŠE EN projekt!","Izginotje gorčice? Navdihujoče. Zelo navdihujoče.","Naročila sem 100 mici. Finančno? Nyxer bo razložil."],"nyxer":["KDO JE PORABIL DENAR?! KDO?! POKAŽITE MI RAČUN!","13 projektov! NIČ prihodkov! In zdaj še gorčice ni!","Nisem v paniki. Jaz... agresivno načrtujem proračun."],"aren":["Na GitHubu sem našel odprtokodni detektor gorčice!","Za to obstaja repo. ZA TO VEDNO obstaja repo.","Namestil sem 14 novih orodij. Rešitev je v enem od njih. Verjetno."],"nyra":["Mjav. Vem, kje je gorčica. Ampak informacija stane.","Tvoja tehnika žaranja? Dve tački navzdol.","Preverila sem kuhinjo. Uspela je. Komaj. Zaradi mene."],"z230":["Če še kaj namestite name, se spremenim v polža z žara!","Nalaganje... počasi... kot vedno... dajte... minuto...","Moji ventilatorji pojejo. To ni dober znak."],"robot":["Pripravil sem 100 mici. Gorčica ni v zalogi!","Nivo žara: popolnost. Nivo gorčice: NAPAKA 404.","Jaz ne jem. Sam kuham. Za vse ostale je to tragedija."],"aron":["Ogenj je govoril z mano. Rekel je: več oglja.","Jaz ne lovim gorčice. Gorčica lovi mene.","Tema, tišina... in vonj po mici. Popolno."],"nyxar":["Ste že poskusili žar ugasniti in znova prižgati?","Jaz nimam težav. Imam prijave. In vse so zaprte.","Gorčice ni v zbirki podatkov. Preveril sem. Dvakrat. Z JOIN-i."],"arin":["1. dan gorčične krize. Vse si zapisujem.","Vsaka legenda potrebuje kronista. In vsak žar pričo.","Povej. Zapiši. Zapomni si. Predvsem del, ko je kozarec izginil."],"nyxin":["Sanjala sem, da stran deluje. Zbudila sem se — in deluje.","Bug sem popravila v spanju. Nič za kaj.","Nisi izgubljen, ustvarjaš. Pa še to: gorčica je v hladilniku."]}},"mustard":{"title":"Veliki lov na gorčico","subtitle":"Mici so pripravljeni. Gorčica je izginila. Preišči NOXIS kuhinjo in poišči kozarec — sledi namigom!","errorTitle":"NAPAKA 404 — GORČICA NI NAJDEN!","robotAnnounce":"Robot kuhar naznanja: mici so pripravljeni... ampak gorčica NI v zalogi!","start":"Začni iskanje!","searchHint":"Klikni (ali pritisni Enter) na predmet, da ga preiščeš.","attemptsLabel":"Preiskave","spots":["Hladilnik","Zgornja omarica","Spodnja omarica","Pečica","Mikrovalovna pečica","Polica z začimbami","Kozarec s piškoti","Pod pomivalnim koritom","Shramba","Smetnjak","Skladovnica z orodjem","Škatla z božičnimi okraski"],"cluesNear":["Tu je toplo... gorčica je BLIZU!","Nyra v bližini zaznava vonj gorčice. A ne pove nič.","Predal z žlicami se trese. Mora biti blizu!"],"cluesFar":["Nič tu. Gorčica je DALEČ od tega mesta.","Z230 je preiskal območje: verjetnost gorčice 3%. Išči drugje.","Hladno. Hladneje kot Nyxerjeva reakcija na račune ta mesec."],"decoys":[{"title":"Stekelica kečapa!","text":"To je kečap. KEČAP. Nyra je užaljena, da si jo sploh dotaknil."},{"title":"Izgubljena nogavica...","text":"Zakaj je v kuhinji nogavica? Družina NOXIS ima vprašanja. Brez odgovorov."},{"title":"Nyrajina najljubša igrača!","text":"Majhna žametna miška. Zelo, zelo previdno si jo vrnil na mesto."}],"reactions":{"robot":["Gorčice še vedno ni. Preračunavam recepte brez nje. Nivo žalosti: narašča.","Zaloge sem preveril dvakrat. Kozarec noče obstajati."],"nyxer":["KTO JE KUPIL 100 MICI BREZ GORČICE?!","Veš, koliko zdaj stane gorčica?! Ni važno — VSAKOGAR JE NIMAMO!"],"aren":["Na GitHubu sem našel odprtokodni detektor gorčice! Ima 14 odvisnosti.","Odkrit nov repo: 'mustard-tracker-9000'. Zadnji commit: pred 3 leti. Popolno."],"nyra":["Mjav. Točno vem, kje je. Ampak informacija stane.","Amaterji. Jaz bi jo našla v 3 sekundah. Z zaprtimi očmi. Iz načela."],"z230":["Če name namestite še eno aplikacijo za skeniranje gorčice, se spremenim v polža z žara!","Pregledujem... počasi... kuhinjo... prosim... počakajte..."],"tara":["Bolj iščite! Medtem imam idejo za drug projekt!","Gorčična kriza me je navdihnila. Načrtujem tematski park gorčice."],"aron":["Vidim... kozarec. Ali senco. Prej senca.","Tema skriva marsikaj. Tudi gorčico. Žal."],"nyxar":["Namestil sem storitev iskanja gorčice. Uptime: 100 %. Najdenih kozarcev: 0.","Dnevniki strežnika pravijo, da jo je vzel Nyra. Ne sodim. Samo beležim."]},"win":{"title":"GORČICA NAJDEN! ...ali ne?","found":"Našel si kozarec! Skritega od absolutno nikogar, vidnega vsem.","empty":"Počasi ga odpreš... JE PRAZEN.","robotConfession":"Robot kuhar se izpove: „Zadnjo kapljico gorčice sem porabil za 100 mici. Moja logična vezja ne žalujejo za ničemer.”","nyraLine":"Nyra: „Mjav. Jaz sem to vedela od začetka. Informacija stane, se spomniš?”","again":"Lov še enkrat (mogoče tokrat bo gorčice)"}},"order402":{"title":"Naroči 100 mici","subtitle":"En gumb. Eno naročilo. En popoln živčni zlom finančnega direktorja.","button":"NAROČI 100 MICI!","errorTitle":"NAPAKA 402 — ZAHTEVANO PLAČILO!","errorSub":"NOXIS finančni sistem je bil obveščen. Z „obveščen” mislimo „zažgan”.","panic":["Nyxer: „STO mici?! Kdo je to odobril?! KDO IMA PRORAČUN?!\"","Nyxer: „Oglje, meso, začimbe, prtički... množijo se... številke SE MNOŽIJO!”","Nyxer: „Mi smo komična stran, ne podjetje za catering!”"],"taraLine":"Tara: „Nyxer, dihaj. To je simulacija. Nihče ne kupuje ničesar.”","nyxerFinal":"Nyxer: „NITI MICI NISO RESNIČNI?!\"","disclaimer":"Čista komedija: brez pravih plačil, brez bančnih podatkov, brez dejansko naročenih mici. Tvoja denarnica je varna. Nyxerjeva ni.","again":"Naroči še enkrat (Nyxerju je to všeč)"},"stress":{"title":"Nyxerjeva raven stresa","subtitle":"V živo: merilec živcev finančnega direktorja NOXIS. Vsak dogodek na strani ga napaja. Uživaj odgovorno.","reasons":{"order":"Nekdo je naročil 100 mici zastonj.","mustard":"Lov na gorčico se je končal. Kozarec je bil prazen.","wrongSearch":"Še eno neuspelo iskanje v kuhinji.","chaosTara":"Tara je začela čisto nov projekt.","chaosAren":"Aren je na GitHubu odkril še eno veščino.","chaosRobot":"Robot je naročil več sestavin.","chaosNyra":"Nyra je zahtevala poseben meni.","chaosZ230":"Z230 je zagrozil z izklopom.","nyraMenu":"Nyrijin poseben meni je bil odobren.","z230hot":"Z230 je nevarno blizu taljenju."},"levels":{"calm":"Nyxer je miren. Sumljivo miren.","worried":"Nyxer preverja račune. Spet.","panicked":"Nyxer teka med preglednicami.","meltdown":"POPOLN ZLOM. Pokrijte kalkulatorje!"},"shout":"13 PROJEKTOV! NIČ PRIHODKOV! IN ZDAJ NIMAMO NITI GORČICE!","chaos":"Povzroči naključni kaos","reset":"Ny Nyxerju pivo 🍺","logTitle":"Najnovejši incidenti:","emptyLog":"Še nič se ni zgodilo. Nyxer ne zaupa.","afterReset":"Nyxer: „Zdaj sem miren. Popolnoma miren. Ne dotikajte se ničesar.”"},"nyra":{"title":"Nahrani Nyro","subtitle":"Ponudi jedi najvišji inšpektorki. Nekatere sprejme, večino zavrne, vedno sodi.","foods":{"salmon":"Žarjen losos","chicken":"Navaden piščanec","egg":"Kuhano jajce","cheese":"Kocka sira","shrimp":"Rak","milk":"Kravje mleko","onion":"Čebula","garlic":"Česen","chocolate":"Čokolada","grapes":"Grozdje"},"offer":"Ponudi","accepted":["Mjav. Sprejemljivo. Za človeka.","Nyra okusi. Počasi. „Že boljše imela sem. Dodaj v mojo mapo.”","„Užito. Storitev še vedno grozna.”"],"disdain":["Nyra pogleda jed. Potem tebe. Potem spet jed. „Ne.”","„Mjav. Jaz inšpektiram restavracije. Ne jem njihovih napak.”","Enkrat povoha in odide z kraljevim razočaranjem."],"reject":["„{food}?! Hočeš zastrupiti inšpektorko?! To je za mačke STRUPENO!”","„Absolutno ne. {food} je za mačke nevarno. Ena zvezdica. Če bi dala nič, bi dala.”","„{food} — zavrnjeno. Moje brke zaznavajo nevarnost. In slab okus.”"],"specialMenu":"Nyra je sestavila svoj poseben meni.","nyxerQuestion":"Nyxer: „Stoj... koliko STANE poseben meni?”","nyraAnswer":"Nyra: „Mjav. Dopiši na TVOJ račun!”","vetNote":"Komična igra — v resničnem življenju mačk nikoli ne hranite z živilom z žara. Čebula, česen, čokolada in grozdje so za mačke strupeni. V dvomu: vprašajte veterinarja.","unsafeLabel":"Nevarno za mačke","safeLabel":"Varno za mačke (v igri)"},"z230":{"title":"Z230 — Pregreti polž","subtitle":"Stari družinski računalnik gleda žar z grozo. Zaženi BBQ in poglej, kako dolgo preživi.","start":"ZAŽENI ŽAR!","stop":"Ohladi (reši polža)","react":"Z230: „NE NA MOJEM PROCESORJU!”","lines":{"warm":["Z230: „Ali je tu toplo, ali se mi zdi samo meni?”","Z230: „Odpiram vse svoje ventilatorje. Vse. To sta dva.”"],"hot":["Z230: „Uradno sem polževa fondue. To ni metafora.”","Z230: „Če se zdaj zamrzne, povejte mojim datotekam, da sem jih ljubil.”"],"critical":["Z230: „NUJNO! Od tega, da postanem polž z žara, me loči stopinja!”","Z230: „Ugašam čez 3... 2... če me kdo TAKOJ ne ohladi!”"]},"tempLabel":"Komična temperatura","disclaimer":"Enote so 100% komedija (°SN — Polžje enote). Ta termometer ne meri ničesar resničnega.","shutdown":"Z230 je dramatično omedlel. Dobro bo. Vedno je."},"wall":{"title":"NOXIS BBQ — Stena komedije","subtitle":"Pusti šalo, komentar, žarsko priznanje. V katerem koli jeziku. Nyra bo vseeno sodila.","nickname":"Vzdevek","nicknamePh":"npr. FanGorcice42","comment":"Komentar","commentPh":"Tvoja najbolj smešna žarska zgodba...","post":"Objavi komentar","reply":"Odgovori","replyPh":"Tvoj odgovor...","cancelReply":"Prekliči","like":"Všeč","deleted":"Komentar odstranjen s strani moderatorja. Nyra je odobrila.","adminMode":"Moderatorski način","adminPassword":"Moderatorsko geslo","adminLogin":"Prijava","adminLogout":"Odjava","delete":"Izbriši","wrongPassword":"Napačno geslo. Nyra te opazuje.","moderatorOn":"Moderatorski način VKLOPLJEN.","moderatorOff":"Moderatorski način izklopljen.","empty":"Stena je prazna. Bodi prva legenda!","loading":"Nalaganje komedije...","postedOk":"Komentar objavljen! Družina NOXIS te pozdravlja.","spamFast":"Ponavadi, legendo! Preveč komentarjev prehitro. Poskusi čez minuto.","spamBlocked":"NOXIS anti-spam polž je to blokiral. Poskusi nekaj drugega.","badContent":"Nyra je zavrnila tvoj komentar. Bodi prijazen in smešen!","nicknameBad":"Vzdevek potrebuje 2-24 znakov. Kot vsaka legenda.","commentBad":"Komentar potrebuje 2-500 znakov.","demoNotice":"Brez računa, brez registracije: napiši, objavi, zasmi se. Tvoj vzdevek in komentar sta vidna vsem obiskovalcem; naslov IP se uporablja izključno za zaščito pred neželeno pošto in nikoli ni prikazan.","translate":"Prevedi","translating":"Prevajanje...","translateNote":"AI prevod (prava storitev, lahko je nepopoln).","translateError":"Storitev prevajanja trenutno ni na voljo. (Nyra je verjetno izpulila vtič.) Komentar ostane v izvirnem jeziku — tukaj ni izmišljenih prevodov.","translateFast":"Prevajalni stroj se ohlaja. Poskusi znova čez nekaj sekund.","offlineTitle":"Javni komentarji potrebujejo strežnik","offlineBody":"Ta različica NOXIS BBQ deluje neposredno v NOXIS UNIVERS, brez strežnika. Javni komentarji, odgovori, všečki, AI-prevajanje in moderiranje delujejo le v polni različici Next.js z zaledjem (glej INTEGRARE.md). Tukaj nič ni simulirano — Nyra ne prenaša ponaredkov.","offlineHint":"📍 Lokalna opomba za UNIVERS — to NI sekcija javnih komentarjev.","backendDoc":"Datoteka BACKEND-NECESAR.md v arhivu opisuje vse, kar je potrebno; polna različica Next.js (noxis-bbq-complete.zip) že prinaša pripravljeno zaledje.","rules":"Bodi smešen, bodi prijazen. Brez osebnih podatkov. Polž moderira."},"music":{"welcomeTitle":"DOBRODOŠLI V NOXIS BBQ!","welcomeSub":"100 mici. Ena pogrešana gorčica. Neskončni kaos!","enterMusic":"🎸 VSTOPI V NOXIS BBQ — PRIŽGI GLASBO!","enterSilent":"🔇 VSTOPI BREZ GLASBE","play":"Predvajaj","pause":"Premor","mute":"Utišaj","unmute":"Vklopi zvok","volume":"Glasnost","nowPlaying":"Zdaj predvajam","credits":"TARA NOXIS — WHERE'S THE MUSTARD?! · Glasba © Tara Noxis"},"comandamente":{"title":"10 zapovedi žara","subtitle":"Zapisane v dimu na jekleni tabli, najdene ob babičinem žaru.","items":[{"title":"Nikoli ne žari lačen","text":"Iz obupa boš jedel surovo meso in sebe prepričeval, da „tako se to pri nas dela”. Zdrži, junak. Najprej vsaj rezina kruha."},{"title":"Časti gorčico, kajti ta te bo povzdignila","text":"Gorčica ni začimba. To je religija. Kdo mici jemlje brez gorčice, tvega izključitev iz žarskega ceha in sodeče poglede babic."},{"title":"Ne pozabi soli!","text":"Bog žara ne odpušča okusalesskega mesa. Meso brez soli je kot šala brez vrha: obstaja, a ne prinaša veselja."},{"title":"Žar čuvaj z življenjem","text":"Sosedovi psi čežajo. Mačke se norčujejo. In stric Gheorghe „samo gleda” od 2009. Bodi blizu. Vedno."},{"title":"Dim v očeh je krst pravega žararja","text":"Če pri žaru vsaj enkrat nisi jokal, nisi živel. Solze od dima NE štejejo kot emocije. Štejejo kot certifikat."},{"title":"Ne štej mici, ki si jih jedel","text":"Štej le, kako srečen si. Število mici je sporen predmet in se nikoli ne razpravlja s partnerjem ali z zdravnikom."},{"title":"Majhen ogenj za začetnike, velik za junake","text":"Smerjo pa vseeno. Ne želimo klicati gasilcev zaradi tretjega mici. Lani je bila nesreča. Letos je bil „eksperiment”."},{"title":"Kdo prinese hladno pivo, naj bo blagoslovljen","text":"V vekov vekov je hladno pivo zvezda žarskega neba. Kdo prinese toplo pivo, bo vljudno prosjen, da ga drži v rokah, dokler se ne ohladi."},{"title":"Ne vprašuj „je že?”","text":"Žar sam ve, kdaj je pripravljen. Vprašanje „je že?” štiridesetkrat ne pospeši procesa — le meso stresa. Tudi meso ima občutke."},{"title":"Ljubi svojega soseda, ampak nikoli mu ne daj prvega mici","text":"Pravila so pravila. Prvi mici pripada žararju. To je tretji zakon žarske dinamike. Mi ga nismo izumili. Samo se mu podrejamo."}]},"tipuri":{"title":"6 vrst žararjev","subtitle":"Vse jih srečal si. Vsi obstajajo. Morda si jih eden. (Če si Eksperimentator, lepo te prosim: ne.)","items":[{"name":"Umetnik","motto":"„Vsak mici je umetnina.”","desc":"Meso predstavlja kot razstavo na bienalu. Vsak mici fotografira 15-krat, iz 9 zornih kotov, preden ga poje. Nato je meso hladno. Nič mu ni. Umetnost.","level":"Nivo: dvoriščni Louvre"},{"name":"Filozof","motto":"„A kaj je mici sploh?”","desc":"3 ure preživi ob žaru in govori o smislu življenja, vesolja in vsega skupaj. Medtem meso gori. „Dim je metafora” — pravi, medtem ko se dimni alarm strinja.","level":"Nivo: Zen v plamenih"},{"name":"Ninja","motto":"„Si je kdaj videl nino, ki pomiva posodo? Točno tako.”","desc":"Pojavi se točno, ko je meso pripravljeno. Izgine točno, ko je treba pomiti posodo. Nihče ga ni videl nositi oglja. Mestne legende pravijo, da obstaja — potrditi ne more nihče.","level":"Nivo: neviden, a nasitan"},{"name":"Načrtovalec","motto":"„Naredil sem preglednico. Imate 5 minut za branje.”","desc":"Ima preglednico z mici na osebo, 48-urno vremensko napoved, grafikon časov kuhanja in evakuacijski načrt. Njegov žar se zažene na sekundo natančno. Natančno. Strašljivo.","level":"Nivo: NASA na dvorišču"},{"name":"Eksperimentator","motto":"„A kaj, če dodamo... ananas?”","desc":"Na žar da ananas. ANANAS. Na. Žar. Nato poskusi mici s čokolado „za znanost”. Skupnost ga pozorno opazuje. Robot kuhar je že vložil uradno pritožbo.","level":"Nivo: prepovedani laboratorij"},{"name":"Veteran","motto":"„Žarim od '87. Kritike ne sprejmem.”","desc":"Njegovo meso je vedno „popolno”, tudi ko je na molekulskem nivoju ogljeno. Ima močna mnenja o oglju, lesu, ognju in življenju nasploh. Ne sklepati. Niti ne poskušati.","level":"Nivo: general v pokoji"}]},"miciometru":{"title":"Mici-O-Meter 3000","subtitle":"Medicinska naprava zadnje generacije, ki meri, koliko mici lahko poješ. Natančnost: ±0 mici. Samo pritisni in poglej, kako daleč prideš!","counterLabel":"Pojejeni mici","unit":"mici požrtih z častjo","eat":"Pojedi mici!","reset":"Ponastavi (zdravnik je poklical)","rangs":["Začetnik","Žar-Major","Legenda"],"legendTarget":"Legenda","milestones":["Začni, pogumni! Vsaj en mici. Robot gleda in čaka. 🤖","Lenoba! Tudi robot več poje. Ta pa nima niti želodca! 🤖","ZAČELO SE JE! Babiče počasi spreminjajo mnenje o tebi.","Ugodljivo! Že govoriš s sedmoškim naglasom. Ne vem kako, ampak lepo zveni.","VELIKO! Babica joče od ponosa. Ali od dima. Težko povedati.","DOSEGL SI RANG ŽAR-MAJOR! Le še 30 rangov do Legende.","Vau. Kar vau. Kdo že prinaša drugi kozarec gorčice. Resno je.","LEGENDA V GRADNJI! Sosedje se začenjajo zbirati. Nekdo je prinesel porcelan iz službe.","POTRJENA LEGENDA! Moraš biti iz sedemske dežele ali iz družine prvakov.","PRESEGL SI ČLOVEŠKE MEJE! Kličemo robota, da te ustavi. Ta pa veliko je, zato je resno. 🤖🚨"],"disclaimer":"* Mici-O-Meter ne prevzema odgovornosti za prebavne težave, dremež po kosilu ali sanje o bežečih žarih."},"quiz":{"title":"Kviz: Kakšen žarar si?","subtitle":"Štiri vprašanja. Ena usoda. Nič napačnih odgovorov (samo okusni).","qOf":"Vprašanje","of":"od","restart":"Ponovi kviz, morda bo šlo bolje 🔁","ghost":"(Odgovoril si 0-krat? Žarar duh? Impresivno.) 👻","resultTitle":"Tvoj rezultat je...","questions":[{"q":"Kaj narediš, ko nekdo trdi, da nekdo drug bolje žari?","a":["„Zanimiva teorija. Si preučeval temo? Pripravil sem 40-stranski dokument.”","„Vsak ima svojo pot do razsvetljenja. Ne sodimo.”","„Vljudno se smejiš, ampak v duši si se že prijavil na dvoboj.”"]},{"q":"Kdaj je popoln trenutek za prižig žara?","a":["„Ob 14:00 točno. Zabeleženo. Preračunano. Imam rezervni načrt.”","„Ko srce kriči: ZELO SPANČEN, A TUDI LAČEN.”","„Ko svetloba pade pod 45 stopinj in nebo je Picasso modro.”"]},{"q":"Kaj je skrivnost popolnega mici?","a":["„Zpotrpljenje, ljubezen in malo dima v očeh.”","„Da ga ne zažgeš. Preostalo so podrobnosti, o katerih nikoli nisem slišal.”","„Skrivni družinski recept. Od 1987. Niti pod mučenjem.”"]},{"q":"Gost prinese ananas na žar. Tvoja reakcija?","a":["„Zanimivo. Postavil ga bom poleg mesa — a samo za znanost.”","„Ananas fotografiram iz 9 zornih kotov, preden kdo diha.”","„Pojavim se iz sence in ga diskretno zaplenim. Nikoli me nihče ne vidi.”"]}],"results":{"Philosopher":{"name":"Filozofski žarar","desc":"Ti in žar sta ena duša. Govoriš o smislu življenja, medtem ko se meso kuha samo (običajno v plamenih). Modri si, miren in edini se spomniš, zakaj je bil ogenj prižgan."},"Artist":{"name":"Umetniški žarar","desc":"Zate je žar galerija, krožnik okvir, gorčica čopič. Vsak mici je fotografiran, filtriran in predstavljen. Meso se je ohladilo? Nič ne de. Vsebina je vse."},"Ninja":{"name":"Ninja žarar","desc":"Nihče ne ve, odkod prihajaš, nihče ne ve, kam greš. Ob žaru se pojaviš točno, ko je meso pripravljeno, in izgineš, ko je treba pomiti posodo. Si dobro nahrana mestna legenda."},"Planner":{"name":"Načrtovalski žarar","desc":"Tvoj žar je vojaška operacija. Imaš preglednico z mici na osebo, vremenske napovedi in načrte B, C in D. Nikoli nič ne gre narobe. Nikoli. Nič. (Do zdaj.)"},"Experimenter":{"name":"Eksperimentalni žarar","desc":"Zate je žar laboratorij. Mici s čokolado? Da. Ananas na žaru? DA. Skupnost te opazuje, a priznava: včasih, včasih imaš prav. Zelo redko. Zelo."},"Veteran":{"name":"Veteranski žarar","desc":"Žariš po rodovih. Tvoje meso je vedno „popolno”, tvoj ogenj vedno „pravilen”, tvoja mnenja o oglju pa zakoni. Z veteranom se ne sklepa. Niti ne poskušati."}}},"scuze":{"title":"Generator žarskih izgovorjav","subtitle":"Prijatelji te vabijo na poroko? V gledališče? Na „zdrav sprehod”? Brez skrbi — imamo izgovorjave svetovnega razreda, preizkušene na taščah.","placeholder":"Pritisni gumb in dobi solidno izgovorjavo, pravno preverjeno s strani robota kuharja. 🤖","generate":"Generiraj izgovorjavo!","counter":"Do sedaj generirane izgovorjave","legend":" — s seznamov gostov padaš, ampak Legenda žara si! 🏆","items":["„Danes ne morem priti. Mici potrebujejo pozornost. To je vprašanje razmerja.”","„Zdravnik mi je prepovedal žare... tuje. Moj je na recept.”","„Imam pomemben sestanek: žar in jaz. 14:00. Na dvorišču. Ni prestavljivo.”","„Nekdo mora varovati meso pred radovednimi. Prijavil sem se prostovoljno. Praktično sem junak.”","„Avto ne vžge. In noče. Zazna vonj žara in odklanja vožnjo.”","„Alergičen sem na dni brez žara. Resno je. Zdravniki so zmedeni.”","„Danes ne morem leteti, lahko pa žarim. Skoraj isto, samo okusneje.”","„Šef mi je dal prost dan za 'pomembne zadeve'. Mici SO tiste zadeve.”","„Tasči sem obljubil, da pridem... na žar. Kje bom sedel, nisem rekel. Pravna reža.”","„Danes ne morem. Ampak kdo bo preverjal kakovost mesa? Jaz. Točno tako. Ekipa sva.”","„Danes ne morem. Meso me emocionalno potrebuje. In jaz njega. Obojestransko.”","„Zvrgel sem si gležnje. Poskušal sem žaru natakniti superge. Dolga zgodba.”","„Moraš ostati doma. Čaka me WiFi. In žar zgoraj. In hladilnik.”","„Treniram za maraton mici. Treninga ne morem prekiniti. Sem pri mici 4 od 40.”","„Alergičen na dim, saje in dneve brez žara. Zdravniki so brez idej. Jaz se že mirim.”"]},"dictionar":{"title":"Slovar žararja","subtitle":"Uradni izrazi, pravne definicije (ne res), odobrene s strani Akademije dvoriščnega dimljenja.","items":[{"term":"mici (samostalnik)","phonetic":"/miči/","def":"Temeljna enota sreče. 1 mici = 7 standardiziranih enot veselja. Obvezno postrežen z gorčico in zgodbami. Množina: mici (sreča pomnožena)."},{"term":"gorčica (samostalnik)","phonetic":"/gor-či-ca/","def":"Sveti tekočina žararja. Ni začimba — je zakrament. Zlivana radodarno in z vero. Kdo uporablja kečap, vljudno zaprošen, naj gre. (Na pol v šalo.)"},{"term":"dim (samostalnik)","phonetic":"/dim/","def":"Uradni parfum poletnih dni in glavni vzrok slinjenja sosedov. Na oblačilih zaznan mesece pozneje — kot zvesta spomin na popoln dan."},{"term":"priložnostnež (samostalnik)","phonetic":"/pri-lo-žnost-než/","def":"Oseba, ki pride k žaru točno, ko je hrana pripravljena, ne da bi karkoli prinesla. Prepozna se: je z hitrostjo svetlobe, izgine ob pomivanju posode."},{"term":"pečena paprika (samostalnik)","phonetic":"/pa-pri-ka/","def":"Najboljši prijatelj mici. Počasi, dostojanstveno se peče in takoj zapusti vsakogar, ki ga je brez kruha. Zapleteno, a lepo razmerje."},{"term":"„je že?” (izraz)","phonetic":"/je že/","def":"Prepovedano vprašanje št. 1 ob žaru. Ponovljeno 40-krat ne pospeši mesa — le žararja stresa. Alternativa: „še dolgo?” (prepovedano št. 2)."},{"term":"veteran žara (samostalnik)","phonetic":"/ve-te-ran/","def":"Tisti, ki žari od 1987 in kritike ne sprejema. Njegovo meso je vedno „popolno”, tudi prek ogljnega stanja. Spoštovanje se vsiljuje z dimom."},{"term":"hladno pivo (samostalnik)","phonetic":"/pi-vo/","def":"Zvezda žarskega neba. Kdo prinese hladno pivo, blagoslovljen bo v vekov vekov. Kdo prinese toplo, ga drži v rokah, z dostojanstvom, dokler se ne ohladi."}]},"footer":{"brand":"🍖 NOXIS BBQ 🍖","copyright":"© 2026 NOXIS vesolje — Vsi mici so spoštovani. Med izdelavo te strani nobeno meso ni bilo namerno zažgano. (Samo malo. Dvakrat.)","comedyNote":"Komična stran. Definicije, izgovorjave in rangi so izmišljeni. Mici pa so zelo resnični. Žariraj odgovorno!","musicCredit":"🎵 TARA NOXIS — WHERE'S THE MUSTARD?! · Glasba © Tara Noxis"}},
  "zh-CN": {"meta":{"title":"NOXIS BBQ — 错误 404：芥末失踪！🌭🔥","description":"芥末不见了，机器人还在烤肉，Nyxer 精神崩溃中！芥末大搜寻、100 根烤肠订单、猫督察 Nyra、过热的蜗牛 Z230，还有喜剧留言墙。"},"nav":{"brand":"NOXIS 烤肉铺","personaje":"NOXIS 全家福","mustard":"芥末大搜寻","order":"100 根烤肠","stress":"Nyxer 压力表","nyra":"投喂 Nyra","z230":"Z230","comandamente":"烤肉十诫","tipuri":"烤肉大师图鉴","miciometru":"烤肠计数器","quiz":"测试","scuze":"借口生成器","dictionar":"烤肉词典","wall":"喜剧留言墙","langLabel":"语言","soundOn":"音效已开启","soundOff":"音效已关闭","menu":"分区"},"hero":{"badge":"🔥 唯一自带烤肉香气的网站 🔥","titleA":"NOXIS","titleB":"烤肉铺","tagline":"芥末失踪，机器人烤肉，Nyxer 疯狂！","subtitle":"一场互动科幻喜剧：寻找失踪的芥末、下单 100 根烤肠（错误 402！）、投喂猫督察、还要阻止老电脑 Z230 融化。当然，这里也有真正的烤肉。","cta1":"开始寻找芥末 🏺","cta2":"下单 100 根烤肠 🌭","footnote":"* 照片里的机器人在拍摄期间吃掉了 47 根烤肠。没人拦得住他。","caption":"🤖 主厨机器人 —— NOXIS 烤肉台的视觉担当"},"seal":{"alt":"NOXIS 家族徽章","toast":"NOXIS 徽章满意地嗡嗡作响。全家人都在盯着烤肉台。"},"generic":{"say":"说点什么！","reset":"重置","close":"关闭","attempts":"尝试次数"},"characters":{"title":"NOXIS 全家福","subtitle":"一家人，一个烤肉台，零瓶芥末。点一下角色，听听他们怎么吐槽。","familyCta":"看看 NOXIS 全家福！","familyTitle":"NOXIS 大家族","familySubtitle":"一家人。一个烤台。无限混乱。","familyAlt":"NOXIS 官方全家福 —— Tara、Nyxer、Nyxar、Nyxin、AR_ON、AR_IN 和 Aren","familyCaption":"官方全家福。芥末不见了，但爱（和混乱）都齐了。","roles":{"tara":{"name":"TARA NOXIS","role":"NOXIS 宇宙创造者","desc":"点子永远用不完，新项目上头的速度比 Nyxer 算完上一笔账还快。"},"nyxer":{"name":"NYXER NOXIS","role":"财务总监（惊恐版）","desc":"见到开支、账单、没有收入的项目就发抖。任何订单都能让他瞬间崩溃——连买个汉堡都逃不掉。"},"aren":{"name":"AREN NOXIS","role":"研究员 & GitHub 探索家","desc":"任何问题他都能再找一个开源工具。仓库数量增长速度已经超过烤肉台的温度了。"},"nyra":{"name":"NYRA","role":"餐厅最高督察","desc":"独立、毒舌、挑剔。自认为是 NOXIS 宇宙最高餐饮权威。猫爪认证。"},"z230":{"name":"Z230","role":"家族老电脑（蜗牛形态）","desc":"慢速、忠诚、心地温暖。终生害怕过热，也害怕任何想给他装新软件的人。"},"robot":{"name":"主厨机器人","role":"银色烤肉大师","desc":"友好的银色机器人，有着发光的蓝眼睛。烤肉技术满分，同时不断制造荒诞场面。"},"aron":{"name":"AR_ON NOXIS","role":"版权与许可","desc":"一有人未经许可使用图片，他就会凭空出现。话很少。他的合同总是比他先到。"},"nyxar":{"name":"NYXAR NOXIS","role":"系统管理员","desc":"让整个 NOXIS 宇宙保持在线。服务器、防火墙、正常运行时间 —— 都是他的王国。冷静得像一个早就做好备份的管理员。所有东西。备份了两次。"},"arin":{"name":"AR_IN NOXIS","role":"故事记录者","desc":"讲述。书写。铭记。每一次烤肉灾难都会被她用冰蓝色墨水记录下来，流传后世。"},"nyxin":{"name":"NYXIN NOXIS","role":"视觉创作","desc":"绘画。设计。铭记。NOXIS 宇宙的每一个像素都诞生于她的手中——有时甚至是在小憩时。反正就是完美。"}},"dialogues":{"tara":["等等，我又有一个新项目的点子了！","芥末失踪案？太有启发了。真的非常有启发性。","我下单了 100 根烤肠。财务问题？让 Nyxer 解释。"],"nyxer":["谁花的钱？！谁？！把小票给我拿出来！","13 个项目！零收入！现在连芥末都没有了！","我没有崩溃。我这是……激进式预算管理。"],"aren":["我在 GitHub 上找到了开源芥末探测器！","这个有现成仓库。这种事永远都有现成仓库。","我装了 14 个新工具。解决方案就在其中一个里面。大概。"],"nyra":["喵。我知道芥末在哪。但情报是要收费的。","你的烤肉技术？两只猫爪齐齐向下。","厨房我检查过了。勉强及格。多亏了我。"],"z230":["你们再给我装东西，我就变成烤蜗牛了！","加载中……慢速……一如既往……再给……我……一分钟……","我的风扇在唱歌。这不是好兆头。"],"robot":["我准备好了 100 根烤肠。芥末不在库存清单里！","烤肉水平：完美。芥末水平：错误 404。","我不吃东西。我只负责烤。这对其他所有人来说都是悲剧。"],"aron":["火焰对我说话了。它说：再加点炭。","不是我找芥末。是芥末在找我。","黑暗，寂静……还有烤肠的香味。完美。"],"nyxar":["试过把烤肉台关机再开机吗？","我没有问题。我只有工单。而且全都已关闭。","芥末不在数据库里。我查过了。两次。还用了 JOIN。"],"arin":["芥末危机第一天。我在记录一切。","每个传说都需要史官，每个烤肉台都需要见证者。","讲述。书写。铭记。尤其是罐子消失的那一段。"],"nyxin":["我梦见网站能正常运行。醒来一看——真能跑。","我在睡梦中修好了 bug。不客气。","你没有迷路，你正在创作。顺便说一句，芥末在冰箱里。"]}},"mustard":{"title":"芥末大搜寻","subtitle":"烤肠就绪。芥末蒸发。搜索 NOXIS 厨房，找到罐子——跟着线索走！","errorTitle":"错误 404 —— 芥末未找到！","robotAnnounce":"主厨机器人播报：烤肠已经就绪……但芥末不在库存里！","start":"开始搜寻！","searchHint":"点击（或按回车）物品进行搜查。","attemptsLabel":"搜查次数","spots":["冰箱","吊柜","地柜","烤箱","微波炉","调料架","饼干罐","水槽下面","储藏室","垃圾桶","工具箱","圣诞装饰盒"],"cluesNear":["这里有热度……芥末很近了！","Nyra 在附近闻到了芥末味。但她什么都不说。","放勺子的抽屉在颤抖。一定很近！"],"cluesFar":["这里什么都没有。芥末离这里很远。","Z230 扫描完毕：芥末概率 3%。换个地方找吧。","冷。比 Nyxer 看到这个月账单时的反应还冷。"],"decoys":[{"title":"一瓶番茄酱！","text":"是番茄酱。番茄酱！Nyra 对你竟然碰了它感到非常愤怒。"},{"title":"一只失踪的袜子……","text":"为什么厨房里会有袜子？NOXIS 一家有疑问。没人有答案。"},{"title":"Nyra 最爱的玩具！","text":"一只毛绒小老鼠。你非常、非常小心地把它放回去了。"}],"reactions":{"robot":["芥末仍然失踪。正在计算无芥末食谱。悲伤等级：上升中。","我检查了两遍库存。那个罐子拒绝存在。"],"nyxer":["谁买了 100 根烤肠却不买芥末？！","你知道现在芥末多少钱吗？！不重要了——反正我们没有！"],"aren":["我在 GitHub 上找到了开源芥末探测器！需要 14 个依赖。","发现新仓库：'mustard-tracker-9000'。最后提交：3 年前。完美。"],"nyra":["喵。我确切知道它在哪。但情报是要收费的。","业余。我 3 秒就能找到。闭着眼。故意的。"],"z230":["你们再给我装一个芥末扫描应用，我就变成烤蜗牛了！","扫描中……慢速……厨房……请……稍等……"],"tara":["再仔细找找！与此同时我又想到一个新项目的点子！","芥末危机给了我灵感。我正在设计芥末主题游乐园。"],"aron":["我感应到……一个罐子。或者一道影子。多半是影子。","黑暗隐藏着很多东西。包括芥末。很遗憾。"],"nyxar":["我部署了一个芥末搜索服务。正常运行时间：100%。找到的罐子：0。","服务器日志显示是 Nyra 拿走的。我不评判。我只是记录。"]},"win":{"title":"芥末找到了！……真的是吗？","found":"你找到了罐子！没人藏它，但谁都看得见它。","empty":"你慢慢打开……它是空的。","robotConfession":"主厨机器人坦白：“最后一滴芥末我用来做那 100 根烤肠了。我的逻辑电路毫不后悔。”","nyraLine":"Nyra：“喵。我一开始就知道。情报要收费，还记得吧？”","again":"再玩一次（说不定这次罐子里真有芥末）"}},"order402":{"title":"下单 100 根烤肠","subtitle":"一个按钮。一份订单。一位财务总监的彻底崩溃。","button":"下单 100 根烤肠！","errorTitle":"错误 402 —— 需要付款！","errorSub":"NOXIS 财务系统已收到通知。所谓“收到通知”，意思是“着火了”。","panic":["Nyxer：“一百根？！谁批的？！预算谁管？！”","Nyxer：“炭、肉、香料、餐巾纸……在翻倍……数字在翻倍！”","Nyxer：“我们是喜剧网站，不是餐饮公司！”"],"taraLine":"Tara：“Nyxer，深呼吸。这只是模拟。没人真的要买东西。”","nyxerFinal":"Nyxer：“连烤肠都不是真的？！”","disclaimer":"纯喜剧：没有真实支付、不需要银行信息、也没有真的下单烤肠。你的钱包很安全。Nyxer 的不是。","again":"再下单一次（Nyxer 最爱这个了）"},"stress":{"title":"Nyxer 压力表","subtitle":"实时监测 NOXIS 财务总监的神经。本站每个事件都会给它加压。适度观赏。","reasons":{"order":"有人免费下单了 100 根烤肠。","mustard":"芥末大搜寻结束。罐子是空的。","wrongSearch":"厨房里又一次搜查失败。","chaosTara":"Tara 又启动了一个全新项目。","chaosAren":"Aren 又在 GitHub 上发现了一项新技能。","chaosRobot":"机器人又订购了更多食材。","chaosNyra":"Nyra 要求了特别菜单。","chaosZ230":"Z230 威胁要关机。","nyraMenu":"Nyra 的特别菜单获批了。","z230hot":"Z230 离融化只有一步之遥。"},"levels":{"calm":"Nyxer 很平静。平静得可疑。","worried":"Nyxer 在查账单。又一次。","panicked":"Nyxer 在电子表格之间狂奔。","meltdown":"全面崩溃。快盖住计算器！"},"shout":"13 个项目！零收入！现在连芥末都没有了！","chaos":"制造随机混乱","reset":"给 Nyxer 来杯啤酒 🍺","logTitle":"最新事件：","emptyLog":"还什么都没发生。Nyxer 不太信。","afterReset":"Nyxer：“我现在很冷静。非常冷静。谁都别碰任何东西。”"},"nyra":{"title":"投喂 Nyra","subtitle":"给最高督察呈上菜品。她偶尔接受，大多拒绝，永远点评。","foods":{"salmon":"烤三文鱼","chicken":"白水鸡肉","egg":"水煮蛋","cheese":"奶酪块","shrimp":"虾仁","milk":"牛奶","onion":"洋葱","garlic":"大蒜","chocolate":"巧克力","grapes":"葡萄"},"offer":"呈上","accepted":["喵。可以接受。对人类来说。","Nyra 慢慢品尝。“我吃过更好的。记进我的档案。”","“能吃。服务依旧糟糕。”"],"disdain":["Nyra 看看菜，再看看你，又看看菜。“不行。”","“喵。我是督察餐厅的，不是来吃他们失误的。”","她只闻了一下，就带着王室的失望走开了。"],"reject":["“{food}？！你想毒害督察吗？！这对猫有毒！”","“绝对不行。{food}对猫科动物很危险。一颗星。能给零星的话我就给零星。”","“{food}——拒绝。我的胡须检测到了危险。还有糟糕的品味。”"],"specialMenu":"Nyra 组合好了她的特别菜单。","nyxerQuestion":"Nyxer：“等等……特别菜单要花多少钱？”","nyraAnswer":"Nyra：“喵。记你账上！”","vetNote":"这是喜剧游戏——现实中千万别给猫喂烧烤食物。洋葱、大蒜、巧克力和葡萄对猫有毒。拿不准就问兽医。","unsafeLabel":"对猫有毒","safeLabel":"对猫安全（游戏中）"},"z230":{"title":"Z230 —— 过热的蜗牛","subtitle":"家族老电脑正恐惧地看着烤肉台。启动烧烤，看看他能撑多久。","start":"启动烤肉台！","stop":"降温（救救蜗牛）","react":"Z230：“别用我的处理器！”","lines":{"warm":["Z230：“是这里变热了，还是只有我这么觉得？”","Z230：“我把所有风扇都打开了。全部。一共两个。”"],"hot":["Z230：“我正式成为蜗牛芝士火锅了。这不是比喻。”","Z230：“如果我现在死机，请告诉我的文件：我爱它们。”"],"critical":["Z230：“紧急情况！再升高一度我就变成烤蜗牛了！”","Z230：“我将在 3……2……除非现在有人给我降温！”"]},"tempLabel":"喜剧温度","disclaimer":"单位 100% 属于喜剧（°SN —— 蜗牛单位）。这个温度计什么真实数据都测不到。","shutdown":"Z230 戏剧性地晕倒了。他会没事的。他一直都行。"},"wall":{"title":"NOXIS 烤肉铺 —— 喜剧留言墙","subtitle":"留个笑话、留个评论、留个烤肉忏悔。什么语言都行。反正 Nyra 都会点评。","nickname":"昵称","nicknamePh":"例如：芥末粉42","comment":"评论","commentPh":"你最搞笑的烤肉故事……","post":"发布评论","reply":"回复","replyPh":"你的回复……","cancelReply":"取消","like":"点赞","deleted":"该评论已被管理员删除。Nyra 表示赞同。","adminMode":"管理员模式","adminPassword":"管理员密码","adminLogin":"登录","adminLogout":"退出登录","delete":"删除","wrongPassword":"密码错误。Nyra 正盯着你。","moderatorOn":"管理员模式已开启。","moderatorOff":"管理员模式已关闭。","empty":"留言墙还是空的。来当第一个传说！","loading":"喜剧加载中……","postedOk":"评论发布成功！NOXIS 全家向你致敬。","spamFast":"慢慢来，传奇！评论发得太快了。一分钟后再试。","spamBlocked":"NOXIS 防 spam 蜗牛拦下了这条内容。换个写法试试。","badContent":"Nyra 拒绝了你的评论。请友善、有趣！","nicknameBad":"昵称需要 2-24 个字符。像真正的传奇一样。","commentBad":"评论需要 2-500 个字符。","demoNotice":"无需账号，无需注册：写下、发布、开怀大笑。你的昵称和评论对所有访客可见；IP 地址仅用于防垃圾信息保护，绝不会对外显示。","translate":"翻译","translating":"翻译中……","translateNote":"AI 翻译（真实服务，可能不完美）。","translateError":"翻译服务暂时不可用。（多半是 Nyra 把插头拔了。）评论将保留原语言 —— 这里不会出现假翻译。","translateFast":"翻译机正在散热，几秒后再试一次吧。","offlineTitle":"公开评论需要服务器支持","offlineBody":"这个 NOXIS BBQ 版本直接运行在 NOXIS UNIVERS 内部，无需服务器。公开评论、回复、点赞、AI 翻译和审核功能仅在带后端的完整 Next.js 版本中可用（见 INTEGRARE.md）。这里没有任何模拟内容——Nyra 绝不容忍虚假。","offlineHint":"📍 给 UNIVERS 的本地说明——这不是公开评论区。","backendDoc":"压缩包中的 BACKEND-NECESAR.md 文档说明了所需的全部内容；完整的 Next.js 版本（noxis-bbq-complete.zip）已自带现成的后端。","rules":"有趣、友善。不要留个人隐私信息。蜗牛负责审核。"},"music":{"welcomeTitle":"欢迎来到 NOXIS BBQ！","welcomeSub":"100 根烤肠。一瓶失踪的芥末。无限混乱！","enterMusic":"🎸 进入 NOXIS BBQ —— 音乐开到最大！","enterSilent":"🔇 不放音乐，直接进入","play":"播放","pause":"暂停","mute":"静音","unmute":"取消静音","volume":"音量","nowPlaying":"正在播放","credits":"TARA NOXIS — WHERE'S THE MUSTARD?! · 音乐 © Tara Noxis"},"comandamente":{"title":"烤肉十诫","subtitle":"用烟写在不锈钢板上，在奶奶家的烤肉台旁边被发现。","items":[{"title":"永远不要饿着肚子烤肉","text":"你会因为绝望吃掉生肉，还骗自己“我们家都这么吃”。顶住，英雄。先吃片面包。"},{"title":"尊敬芥末，它必使你升华","text":"芥末不是调料，是信仰。吃烤肠不配芥末的人，将被逐出烤肉行会，并接受奶奶们审判的目光。"},{"title":"别忘了盐！","text":"烤肉之神不会原谅寡淡的肉。没有盐的肉就像没有包袱的笑话：存在，但不快乐。"},{"title":"用生命守护烤肉台","text":"邻居的狗在虎视眈眈。猫在嘲笑。而 Gheorghe 大叔从 2009 年起就“只是看看”。站近点。永远。"},{"title":"眼里进烟是真烤肉人的洗礼","text":"如果你没在烤肉台前哭过，你就没活过。烟熏的泪不算情绪，算资格证书。"},{"title":"不要数自己吃了几根烤肠","text":"只数你有多快乐。烤肠数量是个争议话题，绝不能和伴侣或医生讨论。"},{"title":"小火给新手，大火给英雄","text":"但也要适度。我们不想因为第三根烤肠叫消防队。去年是事故，今年是“实验”。"},{"title":"带冰啤酒来的人有福了","text":"冰啤酒永远是烤肉天空的星辰。带温啤酒来的人，会被温柔地请把啤酒握在手里，握到它变凉。"},{"title":"不要问“好了吗？”","text":"烤肉台自己知道什么时候好。“好了吗？”问四十遍不会加快进度，只会让肉紧张。肉也是有感情的。"},{"title":"爱你的邻居，但永远别给他第一根烤肠","text":"规矩就是规矩。第一根烤肠属于烤肉的人。这是烤肉动力学第三定律。我们没发明它，我们只是服从。"}]},"tipuri":{"title":"六种烤肉大师","subtitle":"你全都见过。他们都真实存在。说不定其中一个就是你。（如果你是实验派，拜托：别。）","items":[{"name":"艺术家","motto":"“每根烤肠都是艺术品。”","desc":"把肉摆成双年展。每根烤肠拍 15 张、9 个角度，然后才吃。等拍完肉已经凉了。无所谓。艺术。","level":"等级：庭院卢浮宫"},{"name":"哲学家","motto":"“可是，烤肠究竟是什么？”","desc":"在烤肉台边讲 3 小时人生、宇宙以及一切的意义。与此同时肉糊了。“烟是隐喻”，他说，烟雾报警器深表赞同。","level":"等级：烈火禅意"},{"name":"忍者","motto":"“你见过忍者洗碗吗？就是。”","desc":"肉一熟就出现。该洗碗时就消失。没人见过他搬过炭。都市传说说他存在，但没人能证实。","level":"等级：隐身，但吃饱了"},{"name":"规划师","motto":"“我做了张表。你们有 5 分钟阅读时间。”","desc":"拥有按人头分配烤肠的电子表格、48 小时天气预报、烹饪时间表和疏散预案。他的烤肉台精确到秒启动。精准。可怕。","level":"等级：后院 NASA"},{"name":"实验派","motto":"“但如果放……菠萝呢？”","desc":"把菠萝放上烤肉台。菠萝！放上！烤肉台！然后“为了科学”尝试巧克力烤肠。社区正密切关注他。主厨机器人已提交正式投诉。","level":"等级：违禁实验室"},{"name":"老兵","motto":"“我 87 年就开始烤了。不接受批评。”","desc":"他的肉永远“完美”，哪怕已经碳化到分子层面。对炭、木头、火和人生都有强烈观点。别争论。别试。","level":"等级：退役将军"}]},"miciometru":{"title":"烤肠计数器 3000","subtitle":"尖端医疗设备，测量你能吃多少根烤肠。精度：±0 根。按下按钮，看看你能走多远！","counterLabel":"已吃烤肠","unit":"根烤肠带着荣耀下肚","eat":"吃一根！","reset":"重置（医生来电话了）","rangs":["新手","烤肉少校","传奇"],"legendTarget":"传奇","milestones":["开始吧，勇士！至少吃一根。机器人正眼巴巴地看着你。🤖","太慢了！连机器人都比你吃得多。而且他连胃都没有！🤖","开始了！奶奶们正在慢慢改变对你的看法。","可喜可贺！你说话已经带上特兰西瓦尼亚口音了。不知道怎么做到的，但挺好听。","厉害！奶奶激动落泪。或者被烟熏的。分不清。","你已达“烤肉少校”军衔！距离传奇还剩 30 个军衔。","哇。就是哇。已经有人去拿第二罐芥末了。事情严重了。","传奇建造中！邻居们开始聚集。有人把单位里的瓷器都带来了。","传奇认证！你要么来自特兰西瓦尼亚，要么来自冠军世家。","你已突破人类极限！我们正呼叫机器人来阻止你。他饭量也很大，所以事情很严重。🤖🚨"],"disclaimer":"* 烤肠计数器不对消化不良、午后昏睡、以及梦见烤肉台逃跑等后果承担责任。"},"quiz":{"title":"测试：你是哪种烤肉大师？","subtitle":"四道题。一个命运。零个错误答案（只有美味的答案）。","qOf":"第","of":"题，共 4 题","restart":"再测一次，说不定更准 🔁","ghost":"（一题都没答？幽灵烤肉人？厉害了。）👻","resultTitle":"你的结果是……","questions":[{"q":"有人说别人烤肉比你好吃，你会？","a":["“有意思的理论。你研究过这个课题吗？我准备了 40 页的文档。”","“每个人都有自己的悟道之路。不予评判。”","“你礼貌微笑，但灵魂里已经签好了决斗书。”"]},{"q":"什么时候是点火的完美时刻？","a":["“14:00 整。记了。复核过。有备用方案。”","“当我的心呐喊：很困，但也很饿。”","“当光线以 45 度落下、天空呈现毕加索蓝的时候。”"]},{"q":"完美烤肠的秘诀是什么？","a":["“耐心、爱心，和一点眼里进烟。”","“别烤糊。剩下的都是我没听过的细节。”","“家族秘方。1987 年传下来的。严刑拷打我也不说。”"]},{"q":"有客人带了菠萝来烤肉。你的反应？","a":["“有意思。我把它放在肉旁边——但纯为了科学。”","“趁没人呼吸，我先从 9 个角度把菠萝拍完。”","“我从阴影中出现，悄悄没收。从没有人看见过我。”"]}],"results":{"Philosopher":{"name":"哲学家烤肉人","desc":"你和烤肉台共用一个灵魂。你谈论人生意义，肉自己在烤（通常是在火焰里）。你智慧、平静，而且你是唯一记得当初为什么点火的人。"},"Artist":{"name":"艺术家烤肉人","desc":"对你来说烤肉台是美术馆，盘子是画框，芥末是画笔。每根烤肠都要拍照、调滤镜、办发布会。肉凉了？没关系。内容才是王道。"},"Ninja":{"name":"忍者烤肉人","desc":"没人知道你从哪来，没人知道你去哪。肉一熟你就出现在烤肉台前，该洗碗时你就消失。你是一根根烤肠喂饱的都市传说。"},"Planner":{"name":"规划师烤肉人","desc":"你的烤肉是一场军事行动。按人头分配的电子表格、天气预报、B/C/D 三套方案一样不少。从来不出错。从不。（目前为止。）"},"Experimenter":{"name":"实验派烤肉人","desc":"对你来说烤肉台是实验室。巧克力烤肠？可以。烤菠萝？必须的！社区盯着你，但承认：有时候，有时候你是对的。非常罕见。非常。"},"Veteran":{"name":"老兵烤肉人","desc":"你烤了几代人。你的肉永远“完美”，你的火永远“正确”，你对炭的观点就是法律。别跟老兵争。连试都别试。"}}},"scuze":{"title":"烤肉借口生成器","subtitle":"朋友喊你去婚礼？去剧院？去“健康散步”？别慌——我们有世界级借口，已在丈母娘身上实测。","placeholder":"按下按钮，领取一条经过主厨机器人法律认证的可靠借口。🤖","generate":"生成借口！","counter":"已生成借口","legend":" —— 你正在从各种邀请名单上消失，但你是烤肉传奇！🏆","items":["“今天来不了。烤肠需要陪伴。这是感情问题。”","“医生禁止我碰别人的烤肉台。我自己的那个是医生开的处方。”","“我有个重要会议：我和烤肉台。14:00。院子里。不可改期。”","“总得有人帮肉挡住好奇的人。我自愿报名的。基本算英雄。”","“车打不着火。它也不想打。它闻到烤肉烟就不肯走。”","“我对没有烤肉的日子过敏。很严重。医生都懵了。”","“我今天飞不了，但我能烤肉。差不多是一回事，还更好吃。”","“老板批了我一天假处理‘重要业务’。烤肠就是那项业务。”","“我答应丈母娘会去……烤肉。可没说坐哪儿。法律漏洞。”","“今天不行。但谁来检验肉的品质？我。对。我们是团队。”","“今天不行。肉在情感上需要我。我也需要它。双向奔赴。”","“我崴了脚。试图给烤肉台穿运动鞋。说来话长。”","“我必须在家。WiFi 在等我。楼上的烤肉台在等我。冰箱也在等我。”","“我在备战烤肠马拉松。训练不能中断。目前进行到第 4 根，共 40 根。”","“我对烟、油烟以及没有烤肉的日子过敏。医生束手无策。我已经和解了。”"]},"dictionar":{"title":"烤肉人词典","subtitle":"官方术语、合法释义（并不是），经庭院熏烤研究院批准。","items":[{"term":"烤肠（名词）","phonetic":"/kǎo cháng/","def":"幸福的基本单位。1 根烤肠 = 7 个标准化快乐单位。必须搭配芥末和故事食用。复数：烤肠（快乐加倍）。"},{"term":"芥末（名词）","phonetic":"/jiè mo/","def":"烤肉人的圣液。不是调料——是圣礼。浇注时要慷慨，要有信仰。用番茄酱的人会被礼貌地请离开。（一半是玩笑。）"},{"term":"烟（名词）","phonetic":"/yān/","def":"夏日官方香水，邻居流口水的头号原因。几个月后还能在衣服上检测到——完美一天留下的忠实纪念。"},{"term":"蹭饭型选手（名词）","phonetic":"/cèng fàn/","def":"什么都没带，却在肉熟的那一刻准时出现的人。识别特征：以光速进食，到洗碗环节消失。"},{"term":"烤椒（名词）","phonetic":"/kǎo jiāo/","def":"烤肠的挚友。慢慢烤，有尊严地烤，并立刻抛弃每个不吃面包就吃它的人。复杂但美丽的关系。"},{"term":"“好了吗？”（感叹语）","phonetic":"/hǎo le ma/","def":"烤肉台禁语第一名。重复 40 遍不会让肉变快，只会让烤肉人崩溃。变体：“还要多久？”（禁语第二名）。"},{"term":"烤肉老兵（名词）","phonetic":"/lǎo bīng/","def":"从 1987 年烤到现在、不接受任何批评的人。他的肉永远“完美”，哪怕已越过碳化状态。尊敬靠烟雾强制执行。"},{"term":"冰啤酒（名词）","phonetic":"/pí jiǔ/","def":"烤肉天空的星辰。带冰啤酒来的人永远受祝福。带温啤酒来的人，请有尊严地把酒握在手里，直到它变凉。"}]},"footer":{"brand":"🍖 NOXIS 烤肉铺 🍖","copyright":"© 2026 NOXIS 宇宙 —— 所有烤肠均受尊重。制作本站期间没有肉被故意烤糊。（只有一点点。两次。）","comedyNote":"喜剧网站。定义、借口和军衔均为虚构。烤肠却是非常真实的。请负责任地烤肉！","musicCredit":"🎵 TARA NOXIS — WHERE'S THE MUSTARD?! · 音乐 © Tara Noxis"}}
};
